/* Reaviva — Banco de preguntas de la Trivia de Sanación.
 * 100% original, secular, alineado con los pilares del programa:
 * límites, amor propio, duelo, contacto cero, patrones, comunicación,
 * relaciones sanas y crecimiento. Las respuestas NUNCA se envían al
 * cliente: el servidor valida y devuelve la explicación al final. */
"use strict";

module.exports = [
  { id: 1, q: "¿Qué es un límite sano?", options: ["Algo que me separa de los demás", "Un límite claro que protege mi bienestar", "Una regla para controlar a otros", "Evitar conversar sobre emociones"], answer: 1, why: "Un límite sano protege tu bienestar sin controlar al otro." },
  { id: 2, q: "Decir «no» sin dar explicaciones largas es…", options: ["Egoísmo", "Falta de educación", "Un derecho", "Señal de desinterés"], answer: 2, why: "No necesitas justificar cada «no»: tu «no» es completo por sí solo." },
  { id: 3, q: "Si alguien se enoja porque pusiste un límite, eso suele significar que…", options: ["El límite estaba mal", "Debes quitar el límite", "Eres culpable de su enojo", "Ese límite hacía falta"], answer: 3, why: "El enojo ante un límite suele mostrar que ese límite era necesario." },
  { id: 4, q: "Un límite se mantiene mejor…", options: ["Con constancia y calma", "Solo si el otro acepta", "Con amenazas", "Gritando"], answer: 0, why: "La constancia tranquila sostiene un límite mejor que cualquier amenaza." },
  { id: 5, q: "El amor propio se demuestra cuando…", options: ["Te pones siempre en último lugar", "Te tratas con el mismo respeto que das a otros", "Te exiges ser perfecto", "Evitas todo conflicto"], answer: 1, why: "Amarte es tratarte con el respeto que das a los demás." },
  { id: 6, q: "¿Cuál es una señal de autoestima sana?", options: ["Necesitar aprobación constante", "Compararte a diario con otros", "Aceptar tus errores sin destruirte", "Nunca pedir ayuda"], answer: 2, why: "Equivocarte no te hace menos valioso: aprender de ello te fortalece." },
  { id: 7, q: "Cuidarte después de una ruptura es…", options: ["Egoísmo", "Perder el tiempo", "Olvidar demasiado rápido", "Parte de sanar"], answer: 3, why: "Cuidarte no es egoísmo: es la base para sanar." },
  { id: 8, q: "La validación más importante viene de…", options: ["Ti mismo", "Tu familia", "Tu ex", "Las redes sociales"], answer: 0, why: "Cuando tu valor depende de ti, nadie puede quitártelo." },
  { id: 9, q: "Después de una ruptura, el duelo es…", options: ["Una debilidad", "Un proceso normal", "Algo que dura una semana", "Señal de que fallaste"], answer: 1, why: "Doler es normal: el duelo es el proceso de soltar lo que fue." },
  { id: 10, q: "Llorar por alguien que te hizo daño significa…", options: ["Que eres débil", "Que debes volver con esa persona", "Que estás procesando la pérdida", "Que no aprendiste nada"], answer: 2, why: "Llorar no es debilidad: es tu corazón procesando la pérdida." },
  { id: 11, q: "¿Qué ayuda más en las primeras semanas de duelo?", options: ["Vigilar sus redes sociales", "Empezar otra relación de inmediato", "Guardar todo el dolor en silencio", "Rutinas simples y apoyo cercano"], answer: 3, why: "Lo simple sostiene: dormir, comer, moverte y hablar con alguien de confianza." },
  { id: 12, q: "Extrañar a alguien que te trató mal es…", options: ["Contradictorio, pero humano", "Prueba de amor verdadero", "Una razón para volver", "Imposible"], answer: 0, why: "Puedes extrañar lo bueno y a la vez saber que mereces algo mejor." },
  { id: 13, q: "El contacto cero sirve para…", options: ["Castigar al otro", "Recuperar tu paz y tu claridad", "Hacer que vuelva", "Demostrar frialdad"], answer: 1, why: "El contacto cero es un regalo para ti: espacio para sanar y ver con claridad." },
  { id: 14, q: "Durante el contacto cero, lo más sano es…", options: ["Guardar sus cosas a la vista", "Revisar su perfil a diario", "Alejar recordatorios y no iniciar contacto", "Pedir noticias por amigos"], answer: 2, why: "Cada vez que no miras atrás, tu corazón avanza un poco más." },
  { id: 15, q: "Si tu ex te escribe durante el contacto cero, lo más sano es…", options: ["Contestar con enojo", "Llamar para cerrar el tema", "Responder de inmediato con un texto largo", "No contestar por impulso y cuidar tu proceso"], answer: 3, why: "No rompas tu proceso por impulso: tu paz vale más que una respuesta rápida." },
  { id: 16, q: "El contacto cero NO es…", options: ["Una estrategia para manipular y que vuelva", "Tiempo para ti", "Un espacio para sanar", "Un límite válido"], answer: 0, why: "Si lo usas para manipular, no es sanación: es una estrategia. El contacto cero es para ti." },
  { id: 17, q: "Repetir el mismo tipo de relación dañina suele indicar…", options: ["Que el amor no existe", "Un patrón que se puede revisar", "Que debes rendirte", "Mala suerte"], answer: 1, why: "Lo que se repite tiene una raíz, y toda raíz se puede trabajar." },
  { id: 18, q: "¿Qué rompe un patrón?", options: ["Cambiar de ciudad", "Esperar a que el otro cambie", "Darse cuenta y elegir distinto", "Tener más citas"], answer: 2, why: "El patrón se rompe cuando ves con claridad y eliges diferente." },
  { id: 19, q: "Elegir siempre personas que no se comprometen puede reflejar…", options: ["Que eres difícil de amar", "Que no hay buenas personas", "Casualidad", "Una herida o creencia sobre lo que mereces"], answer: 3, why: "A veces elegimos lo familiar, no lo sano. Revisar eso lo cambia todo." },
  { id: 20, q: "La primera señal de un patrón repetido es…", options: ["Sentir lo mismo con personas distintas", "Aburrirse rápido", "Que todo sale mal", "Discutir mucho"], answer: 0, why: "Si la historia se siente igual con alguien nuevo, el patrón eres tú el que lo repite." },
  { id: 21, q: "Comunicar lo que sientes sin atacar se llama…", options: ["Manipulación", "Asertividad", "Pasividad", "Frialdad"], answer: 1, why: "Ser asertivo es decir lo que sientes con respeto, sin herir ni callarte." },
  { id: 22, q: "Decir «yo siento que…» en vez de «tú siempre…» ayuda porque…", options: ["Suena más bonito", "Evita el tema", "Habla de ti sin acusar al otro", "Le da la razón al otro"], answer: 2, why: "Hablar desde lo que sientes abre la conversación; acusar la cierra." },
  { id: 23, q: "Escuchar de verdad significa…", options: ["Cambiar de tema rápido", "Preparar tu respuesta mientras el otro habla", "Dar consejos de inmediato", "Entender lo que el otro siente antes de responder"], answer: 3, why: "Escuchar es entender primero y responder después." },
  { id: 24, q: "Si algo te molesta, lo más sano es…", options: ["Decirlo con calma y a tiempo", "Esperar a que el otro adivine", "Guardarlo hasta explotar", "Publicarlo en redes"], answer: 0, why: "Lo que no se dice a tiempo, se dice con enojo después." },
  { id: 25, q: "Una relación sana se reconoce porque…", options: ["Nunca hay discusiones", "Hay respeto incluso en el desacuerdo", "Todo es perfecto", "Uno manda siempre"], answer: 1, why: "Discutir no es el problema: faltarse el respeto, sí." },
  { id: 26, q: "Los celos constantes son…", options: ["Prueba de amor", "Algo romántico", "Una señal de inseguridad que hay que atender", "Normales siempre"], answer: 2, why: "Los celos no son amor: son inseguridad pidiendo atención." },
  { id: 27, q: "El respeto en pareja incluye…", options: ["Decidir por el otro", "Hablar mal en público", "Revisar el celular del otro", "Aceptar un «no» sin castigo"], answer: 3, why: "Respetar es aceptar el «no» sin enojo ni castigo." },
  { id: 28, q: "Pedir perdón de verdad implica…", options: ["Reconocer el daño y cambiar la conducta", "Olvidar rápido", "Decir «perdón, pero tú…»", "Dar un regalo"], answer: 0, why: "El perdón se demuestra con hechos, no solo con palabras." },
  { id: 29, q: "Sanar significa…", options: ["Olvidar por completo", "Que el recuerdo deja de mandar tu vida", "No sentir nada nunca", "Volver a lo de antes"], answer: 1, why: "Sanar no es olvidar: es que el recuerdo ya no te controla." },
  { id: 30, q: "Un hábito que ayuda a sanar es…", options: ["Trabajar sin parar", "Dormir poco", "Escribir lo que sientes", "Aislarte siempre"], answer: 2, why: "Escribir ordena lo que sientes y te ayuda a soltarlo." },
  { id: 31, q: "Compararte con la sanación de otros…", options: ["Acelera todo", "Te motiva siempre", "Es necesario para avanzar", "No sirve: cada proceso tiene su ritmo"], answer: 3, why: "Tu ritmo es tuyo: compararte solo te hace sentir que vas tarde." },
  { id: 32, q: "Pedir ayuda profesional es…", options: ["Un acto de valentía y cuidado", "Señal de debilidad", "Solo para casos graves", "Perder el tiempo"], answer: 0, why: "Pedir ayuda no es debilidad: es cuidarte en serio." },
  { id: 33, q: "La paciencia contigo mismo en el proceso es…", options: ["Una excusa", "Esencial: sanar lleva tiempo", "Innecesaria", "Opcional"], answer: 1, why: "Nadie sana en línea recta. La paciencia es parte del proceso." },
  { id: 34, q: "¿Qué construye confianza después de una traición?", options: ["Promesas bonitas", "Control total", "Hechos constantes en el tiempo", "Olvidar rápido"], answer: 2, why: "La confianza se reconstruye con hechos repetidos, no con promesas." },
  { id: 35, q: "El perdón sano es…", options: ["Olvidar sin más", "Justificar lo que pasó", "Volver siempre con esa persona", "Soltar la carga para tu paz, con o sin reconciliación"], answer: 3, why: "Perdonar es soltar la carga para ti, no justificar al otro ni volver con él." },
  { id: 36, q: "Una señal de que estás sanando es…", options: ["Pensar en eso sin que te derrumbe", "Salir con alguien nuevo de inmediato", "No llorar nunca", "Borrar todo recuerdo"], answer: 0, why: "Cuando el recuerdo ya no te tumba, estás sanando." },
  { id: 37, q: "Tu valor después de una ruptura…", options: ["Se perdió", "No cambió: sigues siendo valioso", "Depende de tu ex", "Hay que ganarlo de nuevo"], answer: 1, why: "Que alguien se vaya no baja tu valor: sigues siendo valioso." },
  { id: 38, q: "Lo primero para una relación sana contigo es…", options: ["Verte perfecto", "Tener pareja", "Tratarte con respeto a diario", "Ganar más dinero"], answer: 2, why: "La relación más larga de tu vida es contigo: trátala bien." },
  { id: 39, q: "Cuando sientes ansiedad por un mensaje sin respuesta, lo más sano es…", options: ["Bloquear de inmediato", "Escribir muchos mensajes seguidos", "Asumir lo peor", "Respirar y darte tiempo antes de reaccionar"], answer: 3, why: "La ansiedad quiere respuestas ya; la calma te devuelve el control." },
  { id: 40, q: "Elegirte a ti mismo significa…", options: ["Ponerte primero sin dañar a otros", "Estar solo siempre", "Ser egoísta", "No amar a nadie"], answer: 0, why: "Elegirte no es egoísmo: es ponerte primero sin pisar a nadie." },
  { id: 41, q: "Poner un límite a un familiar que opina de tu vida es…", options: ["Ser desagradecido", "Sano: tu vida la decides tú", "Falta de respeto", "Romper la familia"], answer: 1, why: "Amar a tu familia no significa dejar que decidan por ti." },
  { id: 42, q: "Si un compañero de trabajo te carga sus tareas, lo más sano es…", options: ["Hacerlo mal a propósito", "Aceptar siempre", "Hablarlo con claridad y ofrecer una alternativa", "Quejarte con todos"], answer: 2, why: "Hablarlo con claridad protege tu tiempo sin romper la relación." },
  { id: 43, q: "Revisar el celular de tu pareja «por seguridad» es…", options: ["Normal en toda pareja", "Amor", "Cuidado", "Una invasión a su privacidad"], answer: 3, why: "La confianza no se construye revisando: se construye respetando." },
  { id: 44, q: "Un límite con consecuencias claras funciona porque…", options: ["El otro sabe qué pasará si lo cruza", "Asusta", "Evita hablar", "Es una amenaza"], answer: 0, why: "Cuando la consecuencia es clara, el límite se toma en serio." },
  { id: 45, q: "Sentir culpa después de poner un límite significa que…", options: ["Eres mala persona", "Estás aprendiendo algo nuevo", "Debes quitarlo", "El límite estaba mal"], answer: 1, why: "La culpa al principio es normal: estás practicando algo nuevo." },
  { id: 46, q: "Decir «no puedo ayudarte esta vez» sin culpa es…", options: ["Falta de amor", "Egoísmo", "Sano: no puedes con todo", "Frialdad"], answer: 2, why: "No puedes dar desde el vacío: cuidarte también es cuidar a otros." },
  { id: 47, q: "Un muro emocional y un límite sano se diferencian en que…", options: ["El límite aísla más", "Ninguno sirve", "Son lo mismo", "El muro aísla y el límite protege sin aislar"], answer: 3, why: "El límite cuida la relación; el muro la cierra por completo." },
  { id: 48, q: "Si alguien cruza tu límite varias veces, lo más sano es…", options: ["Aplicar la consecuencia que anunciaste", "Rendirse", "Seguir avisando igual", "Gritar más fuerte"], answer: 0, why: "Un límite sin consecuencia se vuelve solo una sugerencia." },
  { id: 49, q: "Poner límites con tu ex por los hijos significa…", options: ["Usar a los hijos de mensajeros", "Comunicarse solo de lo necesario, con respeto", "No hablar nunca", "Pelear en cada entrega"], answer: 1, why: "Los hijos no son mensajeros: la comunicación va de adulto a adulto." },
  { id: 50, q: "Tu tiempo libre también merece límites porque…", options: ["El trabajo es lo único", "No tienes nada que hacer", "Descansar te permite estar bien para los demás", "Eres flojo"], answer: 2, why: "Descansar no es perder el tiempo: es recargar para todo lo demás." },
  { id: 51, q: "Prestar dinero que no puedes prestar por no decir que no…", options: ["Siempre vuelve", "Es lo correcto", "Es generosidad", "Te pone en riesgo a ti"], answer: 3, why: "Ayudar no debe dejarte a ti en problemas." },
  { id: 52, q: "Un límite se puede renegociar cuando…", options: ["Las circunstancias cambian y tú lo decides", "El otro se enoja", "Te presionan", "Nunca"], answer: 0, why: "Tus límites son tuyos: puedes ajustarlos cuando tú lo decidas." },
  { id: 53, q: "Hablarte con amabilidad cuando te equivocas se llama…", options: ["Debilidad", "Autocompasión", "Negación", "Excusarte"], answer: 1, why: "Tratarte con amabilidad no es excusarte: es aprender sin destruirte." },
  { id: 54, q: "Compararte con vidas de redes sociales suele…", options: ["Ayudarte a crecer", "Motivarte siempre", "Hacerte sentir insuficiente sin razón", "Mostrar la realidad"], answer: 2, why: "En redes ves lo mejor de otros contra tu día común: no es una comparación justa." },
  { id: 55, q: "Creer que no mereces algo bueno es…", options: ["Modestia", "Realismo", "La verdad", "Una creencia que se puede revisar"], answer: 3, why: "Lo que crees de ti se aprendió, y lo aprendido se puede revisar." },
  { id: 56, q: "Dedicar tiempo a lo que te gusta después de una ruptura…", options: ["Te recuerda quién eres", "Es egoísmo", "No ayuda", "Es perder el tiempo"], answer: 0, why: "Volver a lo que te gusta es volver a ti." },
  { id: 57, q: "La vergüenza por un error se sana mejor…", options: ["Negándolo", "Hablándolo con alguien de confianza", "Castigándote", "Escondiéndolo"], answer: 1, why: "La vergüenza pierde fuerza cuando se habla en un lugar seguro." },
  { id: 58, q: "Celebrar un logro pequeño es…", options: ["Arrogancia", "Presumir", "Reconocer tu esfuerzo", "Innecesario"], answer: 2, why: "Reconocer tu esfuerzo te da fuerza para el siguiente paso." },
  { id: 59, q: "Estar solo un tiempo después de una ruptura puede ser…", options: ["Peligroso", "Aburrido siempre", "Un fracaso", "Un espacio para reencontrarte"], answer: 3, why: "Estar contigo no es estar solo: es reencontrarte." },
  { id: 60, q: "Exigirte ser perfecto te…", options: ["Agota y te hace sentir insuficiente", "Hace feliz", "Hace mejor", "Garantiza éxito"], answer: 0, why: "La perfección no existe: exigirla solo te agota." },
  { id: 61, q: "Perdonarte por lo que no supiste hacer antes es…", options: ["Justificarte", "Parte de crecer", "Olvidar", "Debilidad"], answer: 1, why: "Hiciste lo que pudiste con lo que sabías: perdonarte es crecer." },
  { id: 62, q: "Reconocer una fortaleza tuya cada día…", options: ["Es vanidad", "No cambia nada", "Fortalece tu autoestima", "Es mentirte"], answer: 2, why: "Ver lo bueno en ti, a diario, cambia cómo te tratas." },
  { id: 63, q: "Tu valor como persona depende de…", options: ["Tu pareja", "Tu trabajo", "Tu salario", "Nada externo: es tuyo"], answer: 3, why: "Tu valor no sube ni baja con nadie: es tuyo." },
  { id: 64, q: "Mirarte al espejo y hablarte con respeto…", options: ["Es un hábito que cambia cómo te ves", "Es ridículo", "No sirve", "Es narcisismo"], answer: 0, why: "Cómo te hablas a diario construye cómo te ves." },
  { id: 65, q: "El duelo después de una ruptura avanza…", options: ["En línea recta", "Con avances y retrocesos", "En una semana", "Solo si no lloras"], answer: 1, why: "Sanar va y viene: un día malo no borra tu avance." },
  { id: 66, q: "Una canción que te recuerda a tu ex y te duele significa…", options: ["Que no has sanado nada", "Que debes volver", "Que un recuerdo tocó una herida, y es normal", "Que fallaste"], answer: 2, why: "Un recuerdo puede doler aunque estés avanzando: es normal." },
  { id: 67, q: "Guardar los objetos de tu ex en una caja fuera de la vista…", options: ["Es odio", "No sirve", "Es negar lo que pasó", "Te da espacio para sanar"], answer: 3, why: "Alejar recordatorios no es negar: es darte aire." },
  { id: 68, q: "Una recaída meses después de estar bien es…", options: ["Parte normal del proceso", "Señal de fracaso", "Imposible", "Volver a cero"], answer: 0, why: "Una recaída no borra meses de avance: es parte del camino." },
  { id: 69, q: "Doler por lo que pudo haber sido y no fue es…", options: ["Una tontería", "Duelo por una ilusión, también válido", "Debilidad", "Egoísmo"], answer: 1, why: "También se llora lo que se soñó y no llegó a ser." },
  { id: 70, q: "Dormir y comer bien durante el duelo…", options: ["No importa", "Es imposible", "Sostiene tu cuerpo mientras sanas", "Es egoísmo"], answer: 2, why: "Tu cuerpo también está en duelo: cuidarlo te sostiene." },
  { id: 71, q: "Hablar del dolor con alguien de confianza…", options: ["Te hace débil", "Es quejarse", "No cambia nada", "Te ayuda a procesarlo"], answer: 3, why: "Poner el dolor en palabras lo hace más liviano." },
  { id: 72, q: "Llorar en el trabajo por un recuerdo…", options: ["Es humano: el duelo no tiene horario", "Es poco profesional siempre", "Significa que no puedes trabajar", "Es vergonzoso"], answer: 0, why: "El duelo no pide permiso: aparece cuando aparece." },
  { id: 73, q: "El aniversario de la ruptura puede…", options: ["No sentirse nada", "Remover emociones aunque estés mejor", "Borrar todo", "Ser igual que otro día siempre"], answer: 1, why: "Las fechas mueven recuerdos: sentir algo ese día es normal." },
  { id: 74, q: "Sanar no tiene un tiempo fijo porque…", options: ["El dolor dura para siempre", "Eres lento", "Cada persona y cada historia son distintas", "No quieres sanar"], answer: 2, why: "No hay calendario para sanar: cada proceso tiene su ritmo." },
  { id: 75, q: "Perder una amistad cercana también puede doler como…", options: ["Algo menor siempre", "Nada", "Una exageración", "Un duelo real"], answer: 3, why: "Las amistades también se lloran: su pérdida es un duelo real." },
  { id: 76, q: "Borrar el número de tu ex durante el contacto cero…", options: ["Te quita una tentación en los momentos débiles", "Es odio", "No sirve de nada", "Es inmaduro"], answer: 0, why: "Si no tienes el número a mano, no escribes en un momento de debilidad." },
  { id: 77, q: "Silenciar o dejar de seguir a tu ex en redes es…", options: ["Una forma de castigarlo", "Cuidar tu paz", "Ser inmaduro", "Perder la batalla"], answer: 1, why: "No ver su vida a diario te deja espacio para sanar la tuya." },
  { id: 78, q: "Si amigos en común te cuentan de tu ex, lo más sano es…", options: ["Aislarte de todos", "Pedir todos los detalles", "Decir que prefieres no saber por ahora", "Enojarte con ellos"], answer: 2, why: "Puedes pedir que no te cuenten: es cuidar tu proceso, no pelear." },
  { id: 79, q: "La idea de escribirle «solo una vez para cerrar» suele ser…", options: ["Necesaria siempre", "La única salida", "La mejor forma de cerrar", "Una excusa para romper el contacto cero"], answer: 3, why: "El cierre no siempre llega hablando: a veces llega soltando." },
  { id: 80, q: "En el cumpleaños de tu ex, durante el contacto cero, lo más sano es…", options: ["No escribir: tu proceso va primero", "Pedirle que vuelva", "Escribirle un mensaje largo", "Llamarlo"], answer: 0, why: "Un día especial no obliga a romper lo que te está sanando." },
  { id: 81, q: "Si hay una emergencia real con tu ex, el contacto cero…", options: ["Se rompe para siempre", "Permite un contacto breve y necesario", "Prohíbe ayudar", "Ya no sirve"], answer: 1, why: "Una emergencia permite un contacto puntual, sin volver a lo de antes." },
  { id: 82, q: "La tentación de escribirle suele ser más fuerte…", options: ["Nunca", "En la mañana", "De noche y en soledad", "En el trabajo"], answer: 2, why: "De noche baja la guardia: ten un plan para esos momentos." },
  { id: 83, q: "Releer conversaciones viejas con tu ex…", options: ["Cierra el ciclo", "Es necesario", "Ayuda a sanar", "Te devuelve al dolor una y otra vez"], answer: 3, why: "Releer el pasado te mantiene viviendo en él." },
  { id: 84, q: "Evitar los lugares que frecuentaban por un tiempo es…", options: ["Cuidarte mientras sanas", "Exageración", "Odio", "Cobardía"], answer: 0, why: "No es huir para siempre: es darte tiempo." },
  { id: 85, q: "Bloquear a tu ex cuando te hace daño con sus mensajes es…", options: ["Inmadurez", "Un límite válido para protegerte", "Perder", "Crueldad"], answer: 1, why: "Bloquear no es odio: es proteger tu paz." },
  { id: 86, q: "Si tu ex vuelve a escribirte después de meses, lo más sano es…", options: ["Volver de inmediato", "Responder de inmediato", "Pensar si responder te conviene a ti", "Bloquear sin pensar"], answer: 2, why: "Que escriba no te obliga a responder: decide desde tu bienestar." },
  { id: 87, q: "El contacto cero se rompe más fácil cuando…", options: ["Duermes bien", "Estás con amigos", "Estás ocupado", "Estás aburrido o triste"], answer: 3, why: "El aburrimiento y la tristeza buscan alivio rápido: prepárate para esos momentos." },
  { id: 88, q: "Guardar las fotos juntos en una carpeta oculta en vez de borrarlas…", options: ["Es válido: no tienes que borrar tu historia", "Es debilidad", "Impide sanar", "Es no soltar"], answer: 0, why: "No necesitas borrar tu historia: basta con no verla todos los días." },
  { id: 89, q: "Elegir parejas parecidas una y otra vez suele pasar porque…", options: ["No hay más personas", "Lo familiar se siente cómodo aunque duela", "Es mala suerte", "El amor es así"], answer: 1, why: "Lo conocido se siente seguro, aunque no sea sano." },
  { id: 90, q: "El «amor a primera vista» que se siente intenso desde el primer día…", options: ["Nunca falla", "Siempre es amor verdadero", "Puede ser química, no necesariamente amor sano", "Es garantía de éxito"], answer: 2, why: "La intensidad no es lo mismo que la salud: el amor sano también da calma." },
  { id: 91, q: "Ignorar las «banderas rojas» al inicio suele pasar porque…", options: ["Son inventos", "Todos lo hacen", "No existen", "La ilusión pesa más que las señales"], answer: 3, why: "Cuando quieres que funcione, es fácil mirar hacia otro lado." },
  { id: 92, q: "Cuando tus amigos te advierten de tu pareja, lo más sano es…", options: ["Escuchar sin defenderte y reflexionar", "Alejarte de ellos", "Enojarte", "Ignorarlos siempre"], answer: 0, why: "Quien te quiere a veces ve desde fuera lo que tú no ves dentro." },
  { id: 93, q: "El rol de «salvador» en una relación significa…", options: ["Ayudar siempre", "Sentir que debes arreglar al otro para que te quiera", "Ser buena persona", "Tener paciencia"], answer: 1, why: "No eres responsable de arreglar a nadie: el amor no es un rescate." },
  { id: 94, q: "Quedarte en una relación por miedo a estar solo es…", options: ["Lo mejor", "Amor", "Una señal para revisar qué te da miedo de ti", "Normal"], answer: 2, why: "El miedo a estar solo no es amor: es una herida pidiendo atención." },
  { id: 95, q: "Decir «todos los hombres/mujeres son iguales» es…", options: ["Protección", "Experiencia", "Una verdad", "Una generalización que te cierra a lo nuevo"], answer: 3, why: "Generalizar te protege del dolor, pero también de lo bueno que viene." },
  { id: 96, q: "Cambiar el guion de tus relaciones empieza por…", options: ["Reconocer qué repites y elegir distinto", "Esperar", "Cambiar de pareja", "Cambiar de ciudad"], answer: 0, why: "El cambio empieza en ti, no en la próxima persona." },
  { id: 97, q: "Tu intuición te avisa de algo que no anda bien cuando…", options: ["Todo es perfecto", "Sientes incomodidad constante aunque no sepas por qué", "Estás feliz", "No hay señales"], answer: 1, why: "Esa incomodidad que no se va merece que la escuches." },
  { id: 98, q: "Empezar una relación nueva con el mismo patrón de antes…", options: ["No importa", "Funciona distinto", "Suele terminar igual", "Es la solución"], answer: 2, why: "Sin revisar el patrón, la historia se repite con otro nombre." },
  { id: 99, q: "Lo que aprendiste de niño sobre el amor…", options: ["Se olvida solo", "Es irrelevante", "No influye", "Puede marcar lo que hoy aceptas como normal"], answer: 3, why: "Lo que viste de niño enseñó qué es «normal» en el amor, y se puede revisar." },
  { id: 100, q: "Pedir ayuda para revisar tus patrones es…", options: ["Un paso valiente", "Innecesario", "Solo para otros", "Debilidad"], answer: 0, why: "Revisar tus patrones con ayuda es de valientes, no de débiles." },
  { id: 101, q: "El tono con el que dices algo…", options: ["No importa", "Puede cambiar todo el mensaje", "Es lo único que importa", "Nadie lo nota"], answer: 1, why: "No es solo qué dices: el tono puede abrir o cerrar la conversación." },
  { id: 102, q: "Hablar de un tema difícil cuando estás calmado…", options: ["Es debilidad", "Es perder tiempo", "Ayuda a que el otro escuche sin defenderse", "No cambia nada"], answer: 2, why: "La calma invita a escuchar; el enojo invita a defenderse." },
  { id: 103, q: "Decir «tú siempre» o «tú nunca» en una discusión…", options: ["Es preciso", "Es honesto siempre", "Ayuda a resolver", "Hace que el otro se defienda en vez de escuchar"], answer: 3, why: "Los absolutos cierran puertas: el otro escucha un ataque, no un problema." },
  { id: 104, q: "Pedir lo que necesitas con claridad es…", options: ["Darle al otro la oportunidad de ayudarte", "Ser egoísta", "Inútil", "Exigir demasiado"], answer: 0, why: "Nadie adivina lo que necesitas: pedirlo con claridad es un regalo para los dos." },
  { id: 105, q: "Discutir por mensajes de texto suele…", options: ["Resolver más rápido", "Empeorar el malentendido por falta de tono", "Ser lo mejor", "Evitar problemas"], answer: 1, why: "Sin tono ni rostro, un texto se lee con el peor ánimo posible." },
  { id: 106, q: "Validar lo que siente el otro significa…", options: ["Callarte", "Estar de acuerdo siempre", "Reconocer que su emoción es real, aunque pienses distinto", "Darle la razón"], answer: 2, why: "Validar no es ceder: es decir «entiendo que sientes eso»." },
  { id: 107, q: "El silencio como castigo en pareja…", options: ["Es maduro", "Es necesario", "Resuelve el problema", "Daña la confianza y no comunica nada"], answer: 3, why: "Castigar con silencio no resuelve: solo acumula distancia." },
  { id: 108, q: "Decir lo difícil con respeto y a tiempo…", options: ["Evita que se acumule hasta explotar", "Es innecesario", "Solo genera pelea", "Arruina todo"], answer: 0, why: "Lo difícil dicho a tiempo pesa menos que guardado por meses." },
  { id: 109, q: "Escuchar sin interrumpir demuestra…", options: ["Debilidad", "Respeto e interés real", "Desinterés", "Que no tienes opinión"], answer: 1, why: "Dejar hablar al otro es decirle «lo que dices me importa»." },
  { id: 110, q: "Llegar a un acuerdo después de discutir requiere…", options: ["Que uno se rinda", "Que uno gane", "Que ambos cedan un poco y se comprometan", "Olvidar el tema"], answer: 2, why: "Un buen acuerdo no tiene perdedor: tiene dos personas comprometidas." },
  { id: 111, q: "Tener amistades fuera de la pareja es…", options: ["Una amenaza", "Falta de amor", "Innecesario", "Sano: nadie puede ser todo tu mundo"], answer: 3, why: "Tener tu propio círculo te hace más fuerte, no menos fiel." },
  { id: 112, q: "Apoyar las metas de tu pareja aunque no sean las tuyas es…", options: ["Amar de verdad", "Sacrificio inútil", "Debilidad", "Perder tiempo"], answer: 0, why: "Amar es alegrarte por lo que al otro le importa." },
  { id: 113, q: "Necesitar espacio personal dentro de una relación es…", options: ["Señal de que algo anda mal", "Normal y sano", "Egoísmo", "Rechazo"], answer: 1, why: "El espacio personal no aleja: permite extrañar y volver con ganas." },
  { id: 114, q: "Reír juntos en pareja…", options: ["Es un lujo", "Es opcional", "Fortalece el vínculo", "No importa"], answer: 2, why: "El humor compartido sostiene más de lo que parece." },
  { id: 115, q: "Respetar a la familia de tu pareja aunque pienses distinto es…", options: ["Innecesario", "Sumisión", "Falso", "Parte del respeto a tu pareja"], answer: 3, why: "Respetar su familia es respetar una parte de su historia." },
  { id: 116, q: "Tomar decisiones importantes juntos significa…", options: ["Escucharse y decidir en equipo", "Evitar decidir", "Competir", "Que uno decide y el otro acepta"], answer: 0, why: "En equipo se decide mejor: dos miradas ven más que una." },
  { id: 117, q: "La intimidad emocional se construye…", options: ["Con apariencias", "Compartiendo lo que sienten con confianza", "Con control", "Con regalos"], answer: 1, why: "La cercanía real nace cuando puedes ser tú sin miedo." },
  { id: 118, q: "Admirar a tu pareja es…", options: ["Peligroso", "Idolatrar", "Un ingrediente que mantiene vivo el cariño", "Innecesario"], answer: 2, why: "Admirar a quien amas mantiene viva la chispa." },
  { id: 119, q: "Después de una pelea fuerte, reparar significa…", options: ["Esperar a que se olvide", "Dormir enojados siempre", "Hacer como si nada", "Hablar, reconocer y acordar cómo seguir"], answer: 3, why: "Reparar es volver a mirarse y decir «esto importa más que tener razón»." },
  { id: 120, q: "Una rutina de cariño en pareja (un mensaje, un café juntos)…", options: ["Mantiene vivo el vínculo en lo cotidiano", "No sirve", "Es obligación", "Es aburrida"], answer: 0, why: "El amor se cuida en lo pequeño y en lo diario." },
  { id: 121, q: "Que tu pareja tenga opiniones distintas a las tuyas…", options: ["Es un problema", "Es normal: dos personas no piensan igual en todo", "Es falta de amor", "Hay que corregirlo"], answer: 1, why: "Pensar distinto no es pelear: es ser dos personas completas." },
  { id: 122, q: "Sentirte seguro para ser tú mismo con tu pareja es…", options: ["Aburrido", "Un lujo", "La base de una relación sana", "Imposible"], answer: 2, why: "Si no puedes ser tú, no es amor: es un papel." },
  { id: 123, q: "Cuidar la relación también cuando todo va bien…", options: ["Es exagerar", "Es desconfianza", "Es innecesario", "Evita que se desgaste en silencio"], answer: 3, why: "Lo que no se cuida, se desgasta aunque no haya crisis." },
  { id: 124, q: "Decir «gracias» por lo cotidiano en pareja…", options: ["Hace sentir visto y valorado al otro", "No cambia nada", "Es obligación", "Es cursi"], answer: 0, why: "Agradecer lo diario le dice al otro «te veo»." },
  { id: 125, q: "Perdonar a alguien sin volver con esa persona es…", options: ["Imposible", "Válido: perdonar no obliga a reconciliarse", "Falso perdón", "Odio disfrazado"], answer: 1, why: "Puedes soltar la carga sin abrir la puerta de nuevo." },
  { id: 126, q: "El rencor guardado por años…", options: ["Desaparece solo", "Te protege", "Te pesa a ti más que al otro", "Es justicia"], answer: 2, why: "El rencor es una carga que llevas tú, no quien te hirió." },
  { id: 127, q: "Reconstruir la confianza rota requiere…", options: ["Solo una disculpa", "Olvidar rápido", "Control total", "Tiempo, hechos y paciencia"], answer: 3, why: "La confianza vuelve con hechos repetidos, no con una sola promesa." },
  { id: 128, q: "Agradecer tres cosas cada día…", options: ["Entrena tu mente a ver lo bueno", "Es conformismo", "No cambia nada", "Es una tontería"], answer: 0, why: "La gratitud diaria cambia el foco: de lo que falta a lo que tienes." },
  { id: 129, q: "Un hábito nuevo se sostiene mejor cuando…", options: ["Es enorme desde el primer día", "Es pequeño y constante", "Depende del ánimo", "Lo haces solo"], answer: 1, why: "Pequeño y constante le gana a grande y abandonado." },
  { id: 130, q: "Mover el cuerpo (caminar, bailar, ejercicio) durante el duelo…", options: ["Solo es para atletas", "No ayuda", "Libera tensión y mejora el ánimo", "Es perder tiempo"], answer: 2, why: "El cuerpo también guarda el dolor: moverlo lo alivia." },
  { id: 131, q: "Escribir un diario de lo que sientes…", options: ["No sirve", "Es perder tiempo", "Es solo para niños", "Te ayuda a entenderte y soltar"], answer: 3, why: "Escribir te deja ver lo que sientes con más claridad." },
  { id: 132, q: "Rodearte de personas que te tratan bien…", options: ["Es parte de sanar", "No importa", "Es huir", "Es egoísmo"], answer: 0, why: "Tu entorno te sostiene o te hunde: elige quién te rodea." },
  { id: 133, q: "Aprender de una relación que terminó…", options: ["Es imposible", "Convierte el dolor en sabiduría", "Es justificar al otro", "No vale la pena"], answer: 1, why: "Cada historia deja una lección si te atreves a mirarla." },
  { id: 134, q: "Tener metas propias después de una ruptura…", options: ["Es egoísmo", "Es huir", "Te da dirección y motivos", "No importa"], answer: 2, why: "Una meta te recuerda que tu vida sigue y vale la pena." },
  { id: 135, q: "Sentir esperanza de nuevo después de mucho dolor…", options: ["Es peligroso", "Es mentirte", "Es ingenuo", "Es señal de que estás sanando"], answer: 3, why: "La esperanza que vuelve es tu corazón diciendo que sigue vivo." },
  { id: 136, q: "Redescubrir quién eres fuera de una relación…", options: ["Es volver a ti", "Es imposible", "Es egoísmo", "Es perder tu identidad"], answer: 0, why: "Fuiste alguien antes de esa relación: esa persona sigue ahí." },
  { id: 137, q: "Celebrar tu progreso aunque aún duela un poco…", options: ["Es mentirte", "Es reconocer lo avanzado sin negar lo que falta", "Es conformarse", "No se debe"], answer: 1, why: "Puedes celebrar el camino y seguir sanando a la vez." },
  { id: 138, q: "Compartir lo que aprendiste con alguien que está pasando lo mismo…", options: ["No sirve", "Es presumir", "Puede ayudarle y dar sentido a tu proceso", "Es meterse"], answer: 2, why: "Tu historia puede ser la luz de alguien que hoy está en la oscuridad." },
  { id: 139, q: "La sanación se nota cuando…", options: ["Tienes nueva pareja", "Nunca lloras", "Ya no recuerdas nada", "Puedes hablar del tema sin que te controle"], answer: 3, why: "Sanar es poder mirar atrás sin que te tumbe." },
  { id: 140, q: "El futuro después de una ruptura…", options: ["Es una página en blanco que tú escribes", "Da igual", "Está cerrado", "Depende de tu ex"], answer: 0, why: "Tu historia no terminó: el próximo capítulo lo escribes tú." },
  { id: 141, q: "Dormir a la misma hora cada noche durante el duelo…", options: ["No cambia nada", "Empeora el insomnio", "Ayuda a tu cuerpo a recuperar su ritmo", "Solo funciona con pastillas"], answer: 2, why: "Un horario regular le enseña a tu cuerpo cuándo descansar." },
  { id: 142, q: "Dejar el celular fuera del dormitorio antes de dormir…", options: ["Evita que revises mensajes que te quitan el sueño", "Es exagerado", "Te aísla de todos", "No tiene efecto"], answer: 0, why: "Sin pantalla cerca, tu mente baja el ritmo y descansa mejor." },
  { id: 143, q: "Si no puedes dormir por dar vueltas a lo mismo, lo más sano es…", options: ["Quedarte en la cama luchando horas", "Tomar café para distraerte", "Escribirle a tu ex", "Levantarte un rato, respirar y volver cuando tengas sueño"], answer: 3, why: "Salir de la cama rompe el círculo de pensamientos y el sueño vuelve más fácil." },
  { id: 144, q: "Una rutina corta antes de dormir (ducha, lectura, luz baja)…", options: ["Es perder el tiempo", "Le avisa a tu cuerpo que es hora de descansar", "Solo sirve para niños", "Genera más ansiedad"], answer: 1, why: "Repetir una rutina calma tu cuerpo y prepara el descanso." },
  { id: 145, q: "Dormir poco varios días seguidos durante el duelo…", options: ["Te hace más fuerte", "Hace que todo duela más y cueste más decidir", "No afecta las emociones", "Ayuda a olvidar"], answer: 1, why: "Sin descanso, el dolor pesa más y la mente se nubla." },
  { id: 146, q: "Evitar el café y las bebidas con cafeína en la tarde…", options: ["No influye en el sueño", "Es innecesario", "Te quita energía", "Ayuda a que el sueño llegue más fácil en la noche"], answer: 3, why: "La cafeína de la tarde sigue despierta cuando tú quieres dormir." },
  { id: 147, q: "Dormir con la habitación oscura y fresca…", options: ["Favorece un sueño más profundo", "No importa para nada", "Da más pesadillas", "Solo importa en verano"], answer: 0, why: "La oscuridad y el fresco le dicen a tu cuerpo que es momento de descansar." },
  { id: 148, q: "Si despiertas a media noche pensando en tu ex, lo más sano es…", options: ["Revisar sus redes para calmarte", "Quedarte despierto hasta el amanecer", "Respirar lento y dejar pasar el pensamiento sin pelear con él", "Escribirle un mensaje"], answer: 2, why: "Los pensamientos pasan más rápido cuando no luchas contra ellos." },
  { id: 149, q: "Una siesta corta (20 o 30 minutos) en la tarde…", options: ["Arruina la noche siempre", "Es señal de pereza", "Puede devolverte energía sin robarte el sueño nocturno", "No sirve para nada"], answer: 2, why: "Una siesta breve recarga sin quitarte el sueño de la noche." },
  { id: 150, q: "Acostarte sin pantallas media hora antes…", options: ["Ayuda a que tu mente se calme antes de dormir", "Es imposible hoy en día", "Te aburre más", "No cambia el sueño"], answer: 0, why: "La luz de la pantalla mantiene despierto a tu cerebro." },
  { id: 151, q: "Tener pesadillas frecuentes después de una ruptura es…", options: ["Señal de que estás empeorando", "Algo que debes ignorar", "Prueba de que no sanas", "Normal: tu mente procesa la pérdida también dormida"], answer: 3, why: "Soñar con lo que duele es parte de cómo tu mente lo va soltando." },
  { id: 152, q: "Despertar cada día a la misma hora, aunque no tengas planes…", options: ["Es innecesario", "Le da estructura a tu día y mejora tu ánimo", "Te cansa más", "Solo sirve si trabajas"], answer: 1, why: "Una hora fija para levantarte ordena el día desde temprano." },
  { id: 153, q: "Caminar 20 minutos al día durante el duelo…", options: ["No es suficiente para nada", "Mueve el cuerpo, aclara la mente y mejora el ánimo", "Solo cansa más", "Es perder el tiempo"], answer: 1, why: "Caminar es poco, pero hace mucho por tu ánimo." },
  { id: 154, q: "Bailar en casa con música que te gusta…", options: ["Es ridículo", "No ayuda", "Es solo para fiestas", "Libera tensión y te devuelve alegría al cuerpo"], answer: 3, why: "Bailar suelta lo que las palabras no alcanzan a decir." },
  { id: 155, q: "Estirar el cuerpo unos minutos al despertar…", options: ["Despierta tus músculos y te da energía para el día", "No sirve de nada", "Es solo para deportistas", "Quita tiempo"], answer: 0, why: "Estirar te recuerda que tu cuerpo también merece atención." },
  { id: 156, q: "Si nunca has hecho ejercicio, lo mejor para empezar es…", options: ["Entrenar dos horas desde el primer día", "Esperar a sentirte perfecto", "Empezar con poco y aumentar despacio", "Copiar la rutina de otra persona"], answer: 2, why: "Empezar suave hace que el hábito dure." },
  { id: 157, q: "Hacer ejercicio con un amigo o en grupo…", options: ["Te distrae del objetivo", "Es incómodo", "Te motiva y te conecta con otros", "No cambia nada"], answer: 2, why: "Moverte acompañado suma apoyo al esfuerzo." },
  { id: 158, q: "Respirar profundo y lento cuando sientes angustia…", options: ["Calma tu cuerpo en pocos minutos", "Es perder el tiempo", "Empeora la angustia", "Solo funciona en clase de yoga"], answer: 0, why: "La respiración lenta le avisa a tu cuerpo que no hay peligro." },
  { id: 159, q: "Tomar agua durante el día, aunque no tengas sed…", options: ["No importa", "Es exagerado", "Solo importa en verano", "Ayuda a tu energía y a tu ánimo"], answer: 3, why: "Un cuerpo hidratado piensa y siente mejor." },
  { id: 160, q: "Un baño caliente al final de un día difícil…", options: ["Es un lujo innecesario", "Relaja tus músculos y baja la tensión del día", "No cambia nada", "Solo quita tiempo"], answer: 1, why: "El agua caliente suelta la tensión que el día acumuló." },
  { id: 161, q: "Escuchar a tu cuerpo y descansar cuando estás agotado…", options: ["Es rendirte", "Es cuidarte: el descanso también es parte de sanar", "Es pereza", "Retrasa tu proceso"], answer: 1, why: "Descansar no es rendirse: es recargar para seguir." },
  { id: 162, q: "Practicar un deporte nuevo después de una ruptura…", options: ["Es una distracción inútil", "Es demasiado tarde", "Es solo para jóvenes", "Te da un reto, gente nueva y algo tuyo"], answer: 3, why: "Un deporte nuevo te recuerda que aún puedes empezar cosas." },
  { id: 163, q: "Comer a horarios regulares durante el duelo…", options: ["Le da estabilidad a tu cuerpo y a tu ánimo", "No importa", "Es imposible", "Es obsesión"], answer: 0, why: "Comer con horario sostiene tu energía cuando todo lo demás se mueve." },
  { id: 164, q: "Si pierdes el apetito por la tristeza, lo más sano es…", options: ["No comer hasta tener hambre", "Saltarte comidas", "Comer porciones pequeñas varias veces al día", "Comer solo dulces"], answer: 2, why: "Poco y seguido mantiene tu cuerpo alimentado aunque no tengas hambre." },
  { id: 165, q: "Cocinarte algo que te gusta, aunque sea simple…", options: ["Es perder el tiempo", "Es egoísta", "Es una forma de cuidarte y celebrar estar contigo", "Solo vale si cocinas para otros"], answer: 2, why: "Cocinar para ti es decirte «merezco algo rico»." },
  { id: 166, q: "Comer muchos dulces para calmar la tristeza…", options: ["Alivia un momento pero luego baja más el ánimo", "Es la mejor solución", "No tiene efectos", "Cura el duelo"], answer: 0, why: "El dulce calma un rato, pero no sostiene tu ánimo." },
  { id: 167, q: "Comer frutas y verduras a diario…", options: ["Le da a tu cuerpo lo que necesita para tener energía", "No influye en el ánimo", "Es solo para dietas", "No importa en el duelo"], answer: 0, why: "Comer bien también alimenta tu estado de ánimo." },
  { id: 168, q: "Tomar alcohol para dormir o para no sentir…", options: ["Es una buena solución", "Ayuda a sanar", "No tiene consecuencias", "Empeora el sueño y alarga el dolor"], answer: 3, why: "El alcohol tapa el dolor un rato y lo devuelve más fuerte." },
  { id: 169, q: "Desayunar algo, aunque sea poco, antes de salir…", options: ["Es innecesario", "Te da energía para empezar el día", "Quita tiempo", "Engorda"], answer: 1, why: "Empezar el día alimentado cambia cómo enfrentas todo lo demás." },
  { id: 170, q: "Compartir una comida con alguien cercano…", options: ["Es incómodo", "Convierte comer en un momento de apoyo y compañía", "No cambia nada", "Es perder tiempo"], answer: 1, why: "Comer acompañado alimenta también el corazón." },
  { id: 171, q: "Preparar tus comidas con calma en vez de comer de prisa…", options: ["Es perder el día", "No cambia nada", "Es solo para chefs", "Te conecta con el presente y baja la ansiedad"], answer: 3, why: "Cocinar con calma es un descanso para la mente." },
  { id: 172, q: "Llevar una botella de agua contigo…", options: ["Te recuerda hidratarte durante el día", "Es una moda", "No sirve", "Es incómodo"], answer: 0, why: "Tener agua cerca hace fácil cuidarte." },
  { id: 173, q: "Escribir en tu diario sin preocuparte por la ortografía ni la letra…", options: ["Te libera para escribir lo que de verdad sientes", "Es un desastre", "No sirve", "Es perder tiempo"], answer: 0, why: "El diario es para ti, no para un examen: lo que importa es soltarlo." },
  { id: 174, q: "Escribir una carta que nunca enviarás a tu ex…", options: ["Es una tontería", "Es peligroso", "Te permite decir lo que quedó pendiente y soltarlo", "Te hace volver atrás"], answer: 2, why: "Decirlo en papel cierra lo que quedó abierto, sin romper tu proceso." },
  { id: 175, q: "Releer tu diario después de unas semanas…", options: ["Es perder el tiempo", "Te hace retroceder", "Te muestra cuánto has avanzado aunque no lo notaras", "Es vanidad"], answer: 2, why: "Ver tu propio avance te da fuerzas para seguir." },
  { id: 176, q: "Escribir tus metas en papel…", options: ["Las vuelve claras y te compromete contigo", "No cambia nada", "Es solo para empresas", "Da mala suerte"], answer: 0, why: "Lo escrito se vuelve un compromiso contigo mismo." },
  { id: 177, q: "Si no sabes qué escribir en tu diario, lo mejor es…", options: ["Esperar a tener algo importante", "Copiar frases de otros", "Dejarlo para otro día", "Empezar con una frase simple: «hoy me siento…»"], answer: 3, why: "Una frase simple abre la puerta; el resto viene solo." },
  { id: 178, q: "Escribir tus pensamientos antes de dormir…", options: ["Te quita el sueño", "Vacía tu mente y te ayuda a descansar", "Es inútil", "Te pone triste"], answer: 1, why: "Dejar los pensamientos en papel libera tu mente para dormir." },
  { id: 179, q: "Llevar un registro de tus pequeños logros…", options: ["Es presumir", "Te recuerda que avanzas incluso en días grises", "No sirve", "Es perder tiempo"], answer: 1, why: "Anotar tus logros te muestra que sí estás avanzando." },
  { id: 180, q: "Escribir lo que quieres en tu próxima relación…", options: ["Es soñar despierto", "Atrae mala suerte", "Es perder tiempo", "Te aclara lo que mereces y lo que no aceptarás"], answer: 3, why: "Saber lo que quieres te ayuda a elegir mejor la próxima vez." },
  { id: 181, q: "Usar el diario para desahogarte en vez de escribirle a tu ex…", options: ["Es cobardía", "No funciona", "Protege tu proceso y suelta la emoción sin consecuencias", "Es lo mismo"], answer: 2, why: "El diario escucha sin romper tu contacto cero." },
  { id: 182, q: "Escribir con la mano en papel, en vez de en el celular…", options: ["Te conecta más con lo que sientes y baja el ritmo", "Es anticuado", "No tiene diferencia", "Es más lento y peor"], answer: 0, why: "Escribir a mano te obliga a ir despacio y sentir cada palabra." },
  { id: 183, q: "Tener una rutina sencilla por la mañana (levantarte, arreglarte, desayunar)…", options: ["Es aburrido", "No cambia nada", "Te da un comienzo estable aunque el día sea difícil", "Es solo para gente ocupada"], answer: 2, why: "Una mañana con orden sostiene el resto del día." },
  { id: 184, q: "Arreglar tu cama cada mañana…", options: ["Es un primer logro pequeño que ordena tu día", "No importa", "Es perder tiempo", "Solo importa si vienen visitas"], answer: 0, why: "Un logro pequeño al despertar abre el día con orden." },
  { id: 185, q: "Tener un horario para las cosas básicas (comer, dormir, moverte)…", options: ["Es rigidez", "Te quita libertad", "Es imposible en duelo", "Le devuelve estructura a tu vida cuando todo se siente caótico"], answer: 3, why: "La estructura sostiene cuando las emociones no paran." },
  { id: 186, q: "Hacer una lista corta de pendientes cada día…", options: ["Es estresante", "Te ayuda a enfocarte y a sentir avance al tachar", "Es inútil", "Es solo para el trabajo"], answer: 1, why: "Tachar pendientes te muestra que el día sí avanzó." },
  { id: 187, q: "Ordenar un rincón de tu casa cada día…", options: ["Es evadir el dolor", "Te da sensación de control y calma poco a poco", "No sirve", "Es obsesión"], answer: 1, why: "Ordenar afuera ayuda a ordenar adentro." },
  { id: 188, q: "Reservar un momento del día solo para ti…", options: ["Es egoísmo", "Es perder tiempo", "Es imposible", "Es cuidar tu energía para todo lo demás"], answer: 3, why: "Un rato para ti no es un lujo: es una necesidad." },
  { id: 189, q: "Empezar el día sin revisar el celular de inmediato…", options: ["Te aísla", "No cambia nada", "Te deja empezar el día con tu propia calma", "Es imposible"], answer: 2, why: "Tu mañana merece empezar contigo, no con la pantalla." },
  { id: 190, q: "Tener un ritual para cerrar el día (apagar luces, leer, respirar)…", options: ["Le avisa a tu mente que el día terminó y puede descansar", "Es una tontería", "Quita tiempo", "Solo sirve para niños"], answer: 0, why: "Cerrar el día con calma prepara una mejor noche." },
  { id: 191, q: "Si un día no cumples tu rutina, lo más sano es…", options: ["Castigarte", "Abandonar la rutina para siempre", "Sentirte un fracaso", "Retomarla al día siguiente sin culpa"], answer: 3, why: "Un día malo no rompe el hábito: retomarlo es lo que cuenta." },
  { id: 192, q: "Planear algo agradable para el fin de semana…", options: ["Es evadir", "Te da algo bonito que esperar durante la semana", "Es gastar de más", "No cambia nada"], answer: 1, why: "Tener algo que esperar ilumina la semana." },
  { id: 193, q: "Poner un límite de tiempo a las redes sociales…", options: ["Te desconecta de todos", "Te devuelve horas para ti y baja la comparación", "Es imposible", "No cambia nada"], answer: 1, why: "Menos pantalla es más tiempo para tu vida real." },
  { id: 194, q: "Dejar de seguir cuentas que te hacen sentir insuficiente…", options: ["Es huir", "Es inmaduro", "No cambia nada", "Es cuidar lo que entra a tu mente cada día"], answer: 3, why: "Lo que ves a diario moldea cómo te sientes contigo." },
  { id: 195, q: "Ver la vida «perfecta» de otros en redes durante el duelo…", options: ["Suele hacerte sentir peor por una comparación injusta", "Te motiva siempre", "Es la realidad", "Te ayuda a sanar"], answer: 0, why: "Comparas tu peor momento con el mejor momento de otros." },
  { id: 196, q: "Silenciar las notificaciones por unas horas al día…", options: ["Te hace perder cosas importantes", "Es grosero", "Te devuelve calma y atención para lo que haces", "No sirve"], answer: 2, why: "Sin notificaciones, tu atención vuelve a ser tuya." },
  { id: 197, q: "Revisar el perfil de tu ex «solo un momento»…", options: ["Te da cierre", "Es inofensivo", "Suele reabrir la herida y quitarte la paz del día", "Te ayuda a seguir"], answer: 2, why: "Un vistazo rápido puede costarte el ánimo de todo el día." },
  { id: 198, q: "Publicar tu dolor en redes para que tu ex lo vea…", options: ["Rara vez trae alivio y expone tu proceso", "Es la mejor forma de cerrar", "Siempre funciona", "Es maduro"], answer: 0, why: "Tu proceso merece privacidad, no público." },
  { id: 199, q: "Guardar el celular durante las comidas…", options: ["Es exagerado", "Te aísla", "No cambia nada", "Te permite disfrutar la comida y la compañía"], answer: 3, why: "Comer sin pantalla devuelve el sabor al momento." },
  { id: 200, q: "Ver series o videos sin parar hasta la madrugada…", options: ["Te ayuda a descansar", "Te roba el sueño y al día siguiente pesa más todo", "Es un buen plan", "No afecta"], answer: 1, why: "Dormir tarde por pantallas cobra factura al día siguiente." },
  { id: 201, q: "Usar el celular solo para cosas útiles en la primera hora del día…", options: ["Es imposible", "Te da una mañana más tranquila y enfocada", "Te retrasa", "No importa"], answer: 1, why: "Cómo empiezas el día marca cómo sigue." },
  { id: 202, q: "Seguir cuentas que te inspiran y te hacen bien…", options: ["Es perder tiempo", "No cambia nada", "Es ingenuo", "Convierte tu pantalla en un lugar que te suma"], answer: 3, why: "Tu feed puede ser un lugar que te levanta en vez de hundirte." },
  { id: 203, q: "Poner música alegre mientras ordenas tu casa…", options: ["Es distraerse", "No cambia nada", "Es perder tiempo", "Hace la tarea más ligera y te levanta el ánimo"], answer: 3, why: "La música convierte una tarea pesada en un rato agradable." },
  { id: 204, q: "Armar una lista de canciones que te levantan el ánimo…", options: ["Te da una herramienta lista para los momentos difíciles", "Es perder tiempo", "No funciona", "Es infantil"], answer: 0, why: "Tener tu lista lista es tener un rescate a un toque." },
  { id: 205, q: "Cantar a todo pulmón en el auto o en la ducha…", options: ["Es vergonzoso", "No sirve", "Libera emoción y te hace sentir vivo", "Es solo para niños"], answer: 2, why: "Cantar suelta lo que llevas guardado." },
  { id: 206, q: "Evitar por un tiempo las canciones que compartían…", options: ["Es negar el pasado", "Es odio", "Es cuidarte mientras la herida cierra", "Es exagerado"], answer: 2, why: "Algunas canciones duelen hoy; mañana serán solo canciones." },
  { id: 207, q: "Descubrir música nueva después de una ruptura…", options: ["Te abre recuerdos nuevos que son solo tuyos", "No cambia nada", "Es traicionar el pasado", "Es perder tiempo"], answer: 0, why: "La música nueva crea recuerdos que no duelen." },
  { id: 208, q: "Escuchar música tranquila antes de dormir…", options: ["No ayuda", "Te despierta", "Es solo para bebés", "Calma tu mente y prepara el descanso"], answer: 3, why: "La música suave baja el ritmo de tus pensamientos." },
  { id: 209, q: "Bailar una canción alegre cuando te sientes bajo…", options: ["Es ridículo", "Mueve tu cuerpo y cambia tu estado de ánimo", "No funciona", "Es negar el dolor"], answer: 1, why: "El cuerpo en movimiento arrastra al ánimo con él." },
  { id: 210, q: "Aprender a tocar un instrumento o cantar…", options: ["Es demasiado tarde", "Te da un reto bonito y un espacio solo tuyo", "Es perder tiempo", "Solo sirve si tienes talento"], answer: 1, why: "Aprender algo nuevo te recuerda que puedes crecer." },
  { id: 211, q: "Caminar al aire libre bajo el sol de la mañana…", options: ["No cambia nada", "Es perder tiempo", "Solo cansa", "Mejora tu ánimo y regula tu sueño"], answer: 3, why: "El sol de la mañana despierta tu cuerpo y tu ánimo." },
  { id: 212, q: "Sentarte en un parque a respirar unos minutos…", options: ["Calma tu mente y te devuelve al presente", "Es perder tiempo", "No sirve", "Es aburrido"], answer: 0, why: "Unos minutos en verde bajan el ruido de la mente." },
  { id: 213, q: "Cuidar una planta en casa…", options: ["Es una carga", "No tiene sentido", "Te da una rutina de cuidado y algo vivo que crece contigo", "Es solo decoración"], answer: 2, why: "Ver crecer algo que cuidas te recuerda que tú también creces." },
  { id: 214, q: "Pasar tiempo cerca del agua (río, mar, lago)…", options: ["No cambia nada", "Es peligroso", "Suele calmar y ordenar los pensamientos", "Es perder el día"], answer: 2, why: "El agua en movimiento calma la mente agitada." },
  { id: 215, q: "Desconectarte en la naturaleza sin celular por un rato…", options: ["Te devuelve silencio y claridad", "Te aísla", "Es imposible", "Es aburrido"], answer: 0, why: "El silencio de la naturaleza deja espacio para escucharte." },
  { id: 216, q: "Hacer una caminata larga en fin de semana…", options: ["Es agotador sin sentido", "No cambia nada", "Es solo para deportistas", "Te despeja, te mueve y te regala aire nuevo"], answer: 3, why: "Caminar lejos de la rutina despeja lo que pesa." },
  { id: 217, q: "Abrir las ventanas y dejar entrar luz y aire a tu casa…", options: ["No importa", "Cambia el ambiente y levanta el ánimo", "Es peligroso", "Solo ensucia"], answer: 1, why: "Luz y aire fresco cambian cómo se siente tu casa." },
  { id: 218, q: "Ver el amanecer o el atardecer con calma…", options: ["Es perder tiempo", "Te recuerda que cada día empieza de nuevo", "No tiene sentido", "Es cursi"], answer: 1, why: "Cada amanecer es un recordatorio de que la vida sigue." },
  { id: 219, q: "Retomar un pasatiempo que dejaste por la relación…", options: ["Es mirar atrás", "Te devuelve una parte de ti que estaba dormida", "Es perder tiempo", "No sirve"], answer: 1, why: "Volver a lo que amabas es volver a ti." },
  { id: 220, q: "Probar una actividad nueva (pintar, cocinar, fotografiar)…", options: ["Es gastar dinero", "Es demasiado tarde", "No tiene sentido", "Te abre un mundo propio y gente nueva"], answer: 3, why: "Algo nuevo te da historias que no tienen nada que ver con el pasado." },
  { id: 221, q: "Leer un libro que te atrapa…", options: ["Te transporta y descansa tu mente del dolor", "Es aburrido", "Es evadir", "No ayuda"], answer: 0, why: "Un buen libro le da vacaciones a tu mente." },
  { id: 222, q: "Ver una película que te hace reír…", options: ["Es negar el dolor", "Es perder tiempo", "Te recuerda que la alegría sigue disponible", "Es infantil"], answer: 2, why: "Reír no borra el dolor, pero te recuerda que sigue habiendo luz." },
  { id: 223, q: "Hacer manualidades o trabajar con las manos…", options: ["Es solo para niños", "Es perder tiempo", "Concentra tu mente y calma la ansiedad", "No sirve"], answer: 2, why: "Las manos ocupadas calman la mente." },
  { id: 224, q: "Jugar un juego de mesa o videojuego con amigos…", options: ["Te conecta y te devuelve momentos ligeros", "Es perder tiempo", "Es infantil", "No ayuda"], answer: 0, why: "Jugar con otros devuelve la ligereza a tu semana." },
  { id: 225, q: "Salir solo a tomar un café o a pasear…", options: ["Es triste", "Es raro", "Es perder tiempo", "Te enseña a disfrutar tu propia compañía"], answer: 3, why: "Disfrutar tu compañía es una de las mejores lecciones." },
  { id: 226, q: "Dedicar una tarde a algo que solo te gusta a ti…", options: ["Es egoísmo", "Es recargar tu energía y celebrar quién eres", "Es perder el día", "Es raro"], answer: 1, why: "Una tarde para ti es una inversión, no un gasto." },
  { id: 227, q: "Si te cuesta concentrarte en el trabajo por el duelo, lo más sano es…", options: ["Exigirte el doble", "Dividir el trabajo en tareas pequeñas y avanzar paso a paso", "Renunciar", "Esconderlo y sufrir en silencio"], answer: 1, why: "Pequeños pasos te devuelven el control sin agotarte." },
  { id: 228, q: "Pedir unos días libres si el duelo te supera…", options: ["Es debilidad", "Es poco profesional", "Es rendirte", "Es cuidarte para volver con más fuerza"], answer: 3, why: "Descansar a tiempo evita que el agotamiento te tumbe." },
  { id: 229, q: "Contarle a alguien de confianza en el trabajo que estás pasando un mal momento…", options: ["Te da apoyo y comprensión en días difíciles", "Es poco profesional", "Te hace ver débil", "No sirve"], answer: 0, why: "Que alguien sepa te quita el peso de fingir que todo está bien." },
  { id: 230, q: "Mantener tu rutina de trabajo durante el duelo…", options: ["Es insensible", "Es evadir", "Te da estructura y propósito mientras sanas", "Es imposible"], answer: 2, why: "El trabajo ordena tus días cuando todo lo demás se mueve." },
  { id: 231, q: "Tomar pausas cortas para respirar durante la jornada…", options: ["Es pereza", "Te atrasa", "Te ayuda a sostener el día sin quebrarte", "Es innecesario"], answer: 2, why: "Unos minutos de aire te devuelven la calma para seguir." },
  { id: 232, q: "Evitar tomar decisiones laborales enormes justo después de la ruptura…", options: ["Te protege de decidir desde el dolor", "Es cobardía", "Es perder oportunidades", "No importa"], answer: 0, why: "Las grandes decisiones esperan a que tu mente esté clara." },
  { id: 233, q: "Revisar tus gastos y armar un presupuesto después de la ruptura…", options: ["Es deprimente", "No cambia nada", "Te devuelve control sobre tu nueva realidad", "Es obsesión"], answer: 2, why: "Saber dónde estás parado con el dinero baja la ansiedad." },
  { id: 234, q: "Separar cuentas o gastos compartidos lo antes posible…", options: ["Evita conflictos y te da independencia", "Es agresión", "No importa", "Es mejor dejarlo para después"], answer: 0, why: "Separar lo económico cierra un lazo que ya no debe atarte." },
  { id: 235, q: "Comprar cosas por impulso para sentirte mejor…", options: ["Es la solución", "No tiene consecuencias", "Es merecido siempre", "Alivia un rato pero suma estrés después"], answer: 3, why: "Comprar por impulso tapa el dolor y deja deudas." },
  { id: 236, q: "Ahorrar aunque sea poco cada mes…", options: ["Es imposible", "Te da seguridad y un colchón para tu nueva etapa", "No sirve", "Es tacañería"], answer: 1, why: "Un poco guardado cada mes construye tu tranquilidad." },
  { id: 237, q: "Cambiar de lugar los muebles de tu cuarto después de la ruptura…", options: ["Es negar lo que pasó", "No cambia nada", "Le da aire nuevo a tu espacio y a tu ánimo", "Es gastar energía"], answer: 2, why: "Un espacio distinto te ayuda a sentir que una etapa nueva empieza." },
  { id: 238, q: "Cambiar la ruta que tomas al trabajo si te trae recuerdos…", options: ["Es huir", "No importa", "Te evita recuerdos dolorosos cada mañana", "Es perder tiempo"], answer: 2, why: "Una ruta nueva es un día que empieza sin ese recuerdo." },
  { id: 239, q: "Mudarte de casa justo después de la ruptura…", options: ["Es la solución perfecta", "Siempre es necesario", "No tiene efectos", "Puede ayudar, pero conviene decidirlo con calma y no desde el impulso"], answer: 3, why: "Un cambio tan grande merece una decisión tranquila, no una huida." },
  { id: 240, q: "Crear un rincón en casa solo para ti (leer, escribir, descansar)…", options: ["Es un lujo", "Te da un refugio propio para recargar", "Es perder espacio", "No sirve"], answer: 1, why: "Un rincón tuyo es un recordatorio diario de que mereces cuidarte." },
  { id: 241, q: "Tus padres te presionan para que vuelvas con tu ex. Lo más sano es…", options: ["Hacerles caso para que no se preocupen", "Agradecer su preocupación y decidir tú", "Pelear con ellos", "Dejar de hablarles"], answer: 1, why: "Tus padres quieren verte bien, pero la decisión de tu vida es tuya." },
  { id: 242, q: "Contarles a tus padres que estás pasando por una ruptura es…", options: ["Una carga para ellos", "Algo que debes ocultar", "Señal de debilidad", "Permitir que te apoyen"], answer: 3, why: "Contarlo no es cargar a nadie: es dejar que quienes te quieren te acompañen." },
  { id: 243, q: "Si tus padres comparan tu ruptura con la de otra persona, lo más sano es…", options: ["Recordarles que cada proceso es distinto", "Aceptar la comparación", "Sentirte menos", "Callarte siempre"], answer: 0, why: "Comparar dolores no ayuda: tu proceso tiene su propio ritmo." },
  { id: 244, q: "Tus padres quieren verte «bien» muy rápido. Lo más sano es…", options: ["Fingir que ya estás bien", "Alejarse de ellos", "Decirles que sanar lleva su tiempo", "Ocultarles cómo te sientes"], answer: 2, why: "Ser honesto sobre tu ritmo evita que finjas una recuperación que aún no llega." },
  { id: 245, q: "Volver a vivir con tus padres por un tiempo tras una ruptura es…", options: ["Un fracaso", "Retroceder", "Un apoyo válido mientras te reorganizas", "Algo vergonzoso"], answer: 2, why: "Aceptar refugio temporal es inteligencia, no fracaso." },
  { id: 246, q: "Tus padres critican a tu ex frente a ti y eso te duele. Lo más sano es…", options: ["Pedirles con calma que no lo hagan frente a ti", "Sumarte a las críticas", "Ignorar lo que sientes", "Dejar de visitarlos"], answer: 0, why: "Puedes amar a tus padres y a la vez pedirles que cuiden tus heridas." },
  { id: 247, q: "Si tus padres se meten en el conflicto con tu ex, lo más sano es…", options: ["Pedirles que tomen tu partido", "Dejar que decidan por ti", "Contarles cada detalle para que te defiendan", "Pedirles que no se involucren en la pelea"], answer: 3, why: "Tu ruptura no es una batalla familiar: proteger a tus padres de ella también es cuidarlos." },
  { id: 248, q: "Pedir consejo a tus padres sobre tu ruptura es sano cuando…", options: ["Haces todo lo que dicen", "Escuchas y decides tú", "Les pides que hablen con tu ex", "Solo si están de acuerdo contigo"], answer: 1, why: "Un consejo suma cuando tú sigues siendo quien decide." },
  { id: 249, q: "Tus padres tuvieron un matrimonio difícil. Eso significa que tú…", options: ["Repetirás la misma historia seguro", "No puedes tener una relación sana", "Debes evitar casarte", "Puedes elegir una historia distinta"], answer: 3, why: "La historia de tus padres no es tu destino: tú escribes la tuya." },
  { id: 250, q: "Agradecer el apoyo de tus padres sin contarles cada detalle es…", options: ["Falta de confianza", "Sano: tu privacidad también importa", "Mentirles", "Ser frío"], answer: 1, why: "Puedes ser cercano sin contar todo: tu vida íntima te pertenece." },
  { id: 251, q: "Cuando tus padres se preocupan demasiado por ti, lo más sano es…", options: ["Ocultarles todo", "Enojarte con ellos", "Contarles con honestidad cómo estás y qué necesitas", "Evitarlos"], answer: 2, why: "La honestidad calma más que el silencio: saber cómo estás les da paz." },
  { id: 252, q: "Si tus padres te dicen «ya supéralo», lo más sano es…", options: ["Decirles que necesitas tiempo y comprensión", "Fingir que ya lo superaste", "Pelear con ellos", "Dejar de contarles cómo te sientes"], answer: 0, why: "Pedir comprensión no es pelear: es enseñarles cómo acompañarte." },
  { id: 253, q: "Al explicar la separación a tus hijos, lo más sano es…", options: ["Usar palabras simples según su edad", "Darles todos los detalles", "No decirles nada", "Decirles que fue culpa de uno"], answer: 0, why: "Los niños entienden más de lo que crees cuando se les habla con claridad y calma." },
  { id: 254, q: "Hablar mal del otro padre o madre frente a tus hijos…", options: ["Les ayuda a entender", "Es necesario para que sepan la verdad", "Los pone en medio de un conflicto que no es suyo", "No les afecta"], answer: 2, why: "Tus hijos aman a ambos: hablar mal del otro padre los lastima a ellos." },
  { id: 255, q: "Usar a tus hijos como confidentes de tu dolor…", options: ["Los hace madurar", "Les pone un peso que no les corresponde", "Fortalece la familia", "Es normal"], answer: 1, why: "Tus hijos necesitan un padre o una madre, no un terapeuta: tu dolor va con adultos." },
  { id: 256, q: "Después de una separación, mantener rutinas estables para tus hijos…", options: ["No importa", "Es imposible", "Los aburre", "Les da seguridad en medio del cambio"], answer: 3, why: "Cuando todo cambia, una rutina conocida les dice que siguen a salvo." },
  { id: 257, q: "Que tus hijos quieran a ambos padres después de la separación es…", options: ["Una traición hacia ti", "Algo que debes evitar", "Natural y sano", "Señal de que no te apoyan"], answer: 2, why: "El amor de tus hijos no se divide: alcanza para los dos." },
  { id: 258, q: "Si tu hijo está triste por la separación, lo más sano es…", options: ["Decirle que no pasa nada", "Distraerlo siempre", "Decirle que sea fuerte", "Escucharlo y validar lo que siente"], answer: 3, why: "Un niño que se siente escuchado aprende que sus emociones importan." },
  { id: 259, q: "Compensar la separación con regalos constantes…", options: ["Funciona siempre", "No reemplaza tu presencia y tu atención", "Es lo mejor", "Los hace felices de verdad"], answer: 1, why: "Lo que tus hijos más necesitan no se compra: es tu tiempo y tu presencia." },
  { id: 260, q: "Decirles a tus hijos que la separación no fue su culpa es…", options: ["Esencial: los niños suelen culparse", "Innecesario", "Confundirlos", "Algo que entenderán solos"], answer: 0, why: "Muchos niños creen en secreto que causaron la ruptura: necesitan oír que no fue así." },
  { id: 261, q: "Presentar una nueva pareja a tus hijos debe hacerse…", options: ["Lo antes posible", "Con tiempo, cuando la relación sea estable", "Sin avisarles", "Solo si ellos lo piden"], answer: 1, why: "Presentar a alguien nuevo con calma protege el corazón de tus hijos." },
  { id: 262, q: "Un cambio en la conducta de tu hijo tras la separación puede ser…", options: ["Una señal de que necesita apoyo", "Simple rebeldía", "Algo que se ignora", "Culpa del otro padre"], answer: 0, why: "Los niños hablan con su conducta: un cambio es una forma de pedir ayuda." },
  { id: 263, q: "Una buena crianza compartida se basa en…", options: ["Ganar cada discusión", "Hablar solo por abogados", "Competir por ser el favorito", "Acuerdos claros y respeto entre adultos"], answer: 3, why: "Cuando los adultos cooperan, los hijos respiran tranquilos." },
  { id: 264, q: "En el cumpleaños de tu hijo, estar ambos padres con cordialidad…", options: ["Es imposible", "Confunde al niño", "Le regala un recuerdo de paz", "Es fingir"], answer: 2, why: "Ver a sus padres en paz, aunque sea un día, es un regalo para tu hijo." },
  { id: 265, q: "Preguntarle a tu hijo por la vida del otro padre…", options: ["Es tu derecho", "Te mantiene informado", "Es necesario", "Lo convierte en espía y lo pone en medio"], answer: 3, why: "Tus hijos no son reporteros: lo que necesites saber, pregúntalo de adulto a adulto." },
  { id: 266, q: "Pedir ayuda para cuidar a tus hijos cuando estás agotado es…", options: ["Fracasar como padre o madre", "Ser irresponsable", "Cuidarte para poder cuidarlos", "Admitir derrota"], answer: 2, why: "Descansar no te hace mal padre: te hace un padre que se cuida para cuidar." },
  { id: 267, q: "Un hermano que te escucha sin juzgar tu dolor es…", options: ["Un apoyo valioso que conviene cuidar", "Alguien que se mete en tu vida", "Igual que cualquier persona", "Una molestia"], answer: 0, why: "Tener a alguien que escucha sin juzgar es uno de los apoyos más grandes." },
  { id: 268, q: "Si un hermano se burla de tu dolor, lo más sano es…", options: ["Reírte aunque te duela", "Decirle con calma que eso te lastima", "Aguantarte en silencio", "Burlarte también"], answer: 1, why: "Poner un límite con cariño también se vale con un hermano." },
  { id: 269, q: "Compararte con un hermano que «sí tiene una pareja estable»…", options: ["Solo te hace sentir que vas tarde", "Te motiva siempre", "Es justo", "Te ayuda a sanar"], answer: 0, why: "Cada hermano vive su historia: compararte no acelera la tuya." },
  { id: 270, q: "Pedirle a un hermano que te acompañe a un trámite o una mudanza difícil es…", options: ["Molestarlo", "Aceptar apoyo de quien te quiere", "Ser dependiente", "Innecesario"], answer: 1, why: "Pedir compañía en un momento difícil es dejar que tu familia te sostenga." },
  { id: 271, q: "Que una crisis reviva viejas rivalidades entre hermanos…", options: ["Significa que no se quieren", "Es el fin de la relación", "Es común y se puede hablar con calma", "No tiene arreglo"], answer: 2, why: "Las crisis remueven lo viejo: hablarlo a tiempo evita que crezca." },
  { id: 272, q: "Si un hermano sigue siendo amigo de tu ex, lo más sano es…", options: ["Exigirle que elija", "Romper con tu hermano", "Prohibirle verlo", "Aceptar que su amistad no es una traición hacia ti"], answer: 3, why: "Que tu hermano conserve una amistad no significa que no esté de tu lado." },
  { id: 273, q: "Cuidar la relación con tus hermanos mientras sanas…", options: ["Es imposible", "No importa", "Te mantiene conectado con quienes te quieren", "Es una carga"], answer: 2, why: "En medio del duelo, tus hermanos pueden ser un ancla de cariño." },
  { id: 274, q: "Si tus hermanos menores te miran como ejemplo, mostrarles que estás sanando…", options: ["Es presumir", "Les enseña que el dolor se puede superar", "No les importa", "Es presión para ti"], answer: 1, why: "Sanar a la vista de tus hermanos les muestra que siempre se puede salir adelante." },
  { id: 275, q: "La relación con tus suegros después de la ruptura…", options: ["Debe seguir igual siempre", "Termina de inmediato", "Es tu obligación mantenerla", "Puede cambiar, y está bien"], answer: 3, why: "Los vínculos se transforman: no tienes que forzar lo que ya cambió." },
  { id: 276, q: "Si tus exsuegros te siguen tratando con cariño, lo más sano es…", options: ["Agradecerlo sin confundirlo con una reconciliación", "Usarlo para volver", "Rechazarlos de inmediato", "Cortar todo contacto"], answer: 0, why: "El cariño de tu exfamilia política puede ser sincero sin ser un puente de regreso." },
  { id: 277, q: "Usar a la familia política para saber de tu ex…", options: ["Es inteligente", "Te da control", "Es inofensivo", "Te mantiene atado a lo que quieres soltar"], answer: 3, why: "Cada noticia que buscas es un hilo que te ata al pasado." },
  { id: 278, q: "Cuando la familia política se mete en las decisiones de la pareja, lo más sano es…", options: ["Que la pareja ponga el límite junta", "Obedecer siempre", "Pelear con ellos", "Dejar que decidan"], answer: 0, why: "Una pareja unida pone los límites junta, con respeto y sin peleas." },
  { id: 279, q: "Si la familia política te culpa de la ruptura, lo más sano es…", options: ["Cargar con toda la culpa", "Recordar que una ruptura es responsabilidad de dos", "Pelear para tener la razón", "Rogarles que te perdonen"], answer: 1, why: "Nadie rompe una relación solo: la culpa compartida no se carga en una sola persona." },
  { id: 280, q: "Que tu exsuegro siga siendo abuelo de tus hijos significa…", options: ["Que sigue metido en tu vida", "Un problema", "Que los niños conservan un vínculo valioso", "Que debes mantener la relación"], answer: 2, why: "Los abuelos son un tesoro para tus hijos, más allá de tu historia con su hijo." },
  { id: 281, q: "Poner límites con la familia política sin romper lazos sanos es…", options: ["Imposible", "Posible con respeto y claridad", "Ser maleducado", "Odiarlos"], answer: 1, why: "Un límite claro protege la relación en vez de romperla." },
  { id: 282, q: "Ir a una reunión familiar donde estará tu exfamilia política es una decisión…", options: ["Que deben tomar otros por ti", "Obligatoria siempre", "Tuya, según cómo te sientas", "Que debes evitar para siempre"], answer: 2, why: "Tú decides cuándo estás listo: nadie más puede medir tu dolor." },
  { id: 283, q: "Que tu familia política opine sobre tu vida después de la ruptura…", options: ["No les da derecho a decidir por ti", "Significa que debes obedecer", "Es su derecho", "Te obliga a explicar todo"], answer: 0, why: "Opinar es una cosa; decidir tu vida es solo tuya." },
  { id: 284, q: "Agradecer a tu exsuegra por su cariño de años es…", options: ["Una forma de volver", "Peligroso", "Innecesario", "Un gesto de gratitud que cierra con paz"], answer: 3, why: "Agradecer lo bueno que viviste no es volver: es cerrar con el corazón en paz." },
  { id: 285, q: "Un amigo que solo te dice «ya supéralo»…", options: ["No está sabiendo acompañarte", "Tiene razón", "Es el mejor apoyo", "Te quiere más que nadie"], answer: 0, why: "Acompañar no es apurar: es estar mientras sanas a tu ritmo." },
  { id: 286, q: "Aceptar invitaciones de amigos a salir, aunque no tengas ganas, puede…", options: ["Empeorar todo", "Ser una traición a tu dolor", "Molestar a tus amigos", "Ayudarte a respirar un poco"], answer: 3, why: "Salir no borra el dolor, pero te recuerda que la vida sigue teniendo momentos buenos." },
  { id: 287, q: "Si una amistad se aleja mientras estás en duelo, puede ser que…", options: ["Nunca te quiso", "Sea tu culpa", "No sepa cómo acompañarte", "Te odie"], answer: 2, why: "No todos saben estar cerca del dolor: a veces se alejan por no saber qué hacer." },
  { id: 288, q: "Aislarte de tus amigos por vergüenza de lo que pasó…", options: ["Es lo mejor", "Te quita apoyo justo cuando más lo necesitas", "Te hace fuerte", "Es maduro"], answer: 1, why: "La vergüenza aísla, pero tus amigos no te juzgan como tú crees." },
  { id: 289, q: "Si tus amigos quieren presentarte gente nueva muy pronto, lo más sano es…", options: ["Aceptar para complacerlos", "Enojarte con ellos", "Decirles que aún no estás listo", "Salir con alguien para olvidar"], answer: 2, why: "Tu ritmo manda: nadie debe apurar tu corazón." },
  { id: 290, q: "Agradecer al amigo que estuvo contigo en tu peor momento…", options: ["Fortalece una amistad que vale oro", "Es innecesario", "Es débil", "Lo aleja"], answer: 0, why: "Decir gracias por estar ahí convierte un apoyo en un vínculo más fuerte." },
  { id: 291, q: "Un amigo que te invita a «vengarte» de tu ex…", options: ["Te está ayudando", "No te está dando un buen consejo", "Tiene razón", "Es leal"], answer: 1, why: "La venganza no sana: solo te ata más al dolor." },
  { id: 292, q: "Hacer nuevas amistades después de una ruptura…", options: ["Es traicionar a los viejos amigos", "Es imposible", "Es perder el tiempo", "Te abre a nuevas personas y experiencias"], answer: 3, why: "Conocer gente nueva no borra lo vivido: suma vida a tu vida." },
  { id: 293, q: "Que una amistad cambie después de tu ruptura…", options: ["Es el fin del mundo", "Es parte de cómo evolucionan las relaciones", "Es tu culpa", "Significa que era falsa"], answer: 1, why: "Las relaciones cambian con la vida: algunas se transforman y otras se sueltan." },
  { id: 294, q: "Un amigo que te acompaña a hacer algo que te daba miedo solo…", options: ["Te hace dependiente", "Te está controlando", "Pierde su tiempo", "Te da valor para dar el paso"], answer: 3, why: "Acompañar no es hacer las cosas por ti: es estar mientras tú las haces." },
  { id: 295, q: "Cargar todo tu dolor sobre un solo amigo…", options: ["Es lo correcto", "Fortalece la amistad siempre", "Puede agotarlo: conviene repartir el apoyo", "Es lo que hacen los amigos"], answer: 2, why: "Repartir tu apoyo entre varias personas cuida a tus amigos y a ti." },
  { id: 296, q: "Un amigo que dice «hay gente peor que tú»…", options: ["Está minimizando tu dolor sin querer", "Te está ayudando", "Tiene razón", "Es el mejor consejo"], answer: 0, why: "Que otros sufran más no hace tu dolor más pequeño: tu dolor también cuenta." },
  { id: 297, q: "Celebrar con amigos tus pequeños avances en la sanación…", options: ["Es presumir", "Es innecesario", "Molesta a otros", "Refuerza tu progreso y te conecta"], answer: 3, why: "Compartir un avance lo hace más real y te recuerda que no estás solo." },
  { id: 298, q: "Un amigo que respeta tu silencio sin presionarte para hablar…", options: ["No le importas", "Te está acompañando a tu manera", "Es indiferente", "No sabe ser amigo"], answer: 1, why: "A veces acompañar es estar en silencio, sin exigir palabras." },
  { id: 299, q: "Retomar viejas amistades que dejaste por tu relación…", options: ["Puede devolverte partes de ti que habías dejado", "Es imposible", "Es una traición", "No vale la pena"], answer: 0, why: "Esas amistades guardan recuerdos de quién eras antes: retomarlas es reencontrarte." },
  { id: 300, q: "Una amistad sana se reconoce porque…", options: ["Te exige estar siempre bien", "Te juzga todo el tiempo", "Puedes ser tú sin explicarte", "Solo está en los buenos momentos"], answer: 2, why: "Con un buen amigo no actúas: simplemente eres." },
  { id: 301, q: "Contar en el trabajo solo lo necesario de tu vida privada es…", options: ["Cuidar tu privacidad", "Ser frío", "Mentir", "Ser antisocial"], answer: 0, why: "No tienes que contar todo: compartir lo necesario también es cuidarte." },
  { id: 302, q: "Un compañero que te cubre en un día difícil merece…", options: ["Nada", "Que le debas un favor eterno", "Tu gratitud sincera", "Que le cuentes todo"], answer: 2, why: "Un gracias sincero reconoce el gesto sin convertirlo en deuda." },
  { id: 303, q: "Si en la oficina circulan rumores sobre tu vida privada, lo más sano es…", options: ["Alimentarlos con detalles", "Pelear con todos", "Contar tu versión a cada uno", "No alimentarlos y seguir con tu trabajo"], answer: 3, why: "Los rumores mueren cuando no les das de comer." },
  { id: 304, q: "Usar el trabajo como refugio en pleno duelo…", options: ["Es la solución definitiva", "Puede ayudarte un tiempo, sin ser tu única salida", "Es malo siempre", "Te sana por completo"], answer: 1, why: "Trabajar te da estructura, pero el dolor también necesita su espacio para sanar." },
  { id: 305, q: "Si tu jefe te pregunta si estás bien, lo más sano es…", options: ["Mentir siempre", "Contarle toda tu historia", "Responder con honestidad breve y seguir", "Ignorarlo"], answer: 2, why: "Una respuesta honesta y breve cuida tu privacidad y tu relación laboral." },
  { id: 306, q: "Tomar decisiones laborales grandes en pleno duelo…", options: ["Es el mejor momento", "Acelera tu sanación", "No tiene riesgo", "Conviene esperar a tener la mente más clara"], answer: 3, why: "En pleno dolor las decisiones salen del impulso: esperar te da claridad." },
  { id: 307, q: "Un compañero que vivió una ruptura parecida y te entiende…", options: ["Puede ser un apoyo valioso en el trabajo", "Es una amenaza", "Quiere tu puesto", "No debes acercarte"], answer: 0, why: "Quien ya pasó por lo mismo entiende sin que tengas que explicar tanto." },
  { id: 308, q: "Separar tu vida personal del trabajo sin fingir que no pasa nada es…", options: ["Imposible", "Un equilibrio sano", "Ser falso", "Ser frío"], answer: 1, why: "Puedes trabajar con profesionalismo y a la vez reconocer que estás pasando un momento difícil." },
  { id: 309, q: "Pedir un día libre para atender tu salud emocional es…", options: ["Una excusa", "Válido: tu salud emocional también importa", "Poco profesional", "Solo para otros"], answer: 1, why: "Cuidar tu salud emocional es tan válido como cuidar una gripe." },
  { id: 310, q: "El trabajo, mientras sanas, puede darte…", options: ["Rutina y un sentido de propósito", "Más dolor siempre", "Solo estrés", "Nada bueno"], answer: 0, why: "Una rutina diaria te sostiene cuando el corazón todavía está en desorden." },
  { id: 311, q: "Una red de apoyo sana está formada por…", options: ["Una sola persona que lo haga todo", "Solo profesionales", "Varias personas en distintos roles", "Nadie: debes solo"], answer: 2, why: "Nadie puede ser todo tu apoyo: varias personas, cada una a su manera, te sostienen mejor." },
  { id: 312, q: "Pedir ayuda concreta, como «¿me acompañas a hacer un trámite?», es…", options: ["Ser exigente", "Molestar", "Peor que pedir ayuda general", "Más fácil para el otro y para ti"], answer: 3, why: "Cuando pides algo concreto, ayudar se vuelve simple para quien te quiere." },
  { id: 313, q: "Aceptar ayuda cuando la necesitas…", options: ["Te hace una carga", "Te hace débil", "Es aprovecharte", "Es permitir que otros te quieran con hechos"], answer: 3, why: "Dejarte ayudar no es ser una carga: es abrir la puerta al cariño." },
  { id: 314, q: "Un grupo de apoyo con personas que pasaron por lo mismo puede…", options: ["Empeorar todo", "Ser una pérdida de tiempo", "Hacerte sentir comprendido y menos solo", "Reemplazar a tus amigos"], answer: 2, why: "Escuchar «a mí también me pasó» alivia como pocas cosas." },
  { id: 315, q: "Participar en actividades de tu comunidad mientras sanas…", options: ["Es perder el tiempo", "Te reconecta con la vida y con gente", "Es huir", "No sirve"], answer: 1, why: "Salir y participar te recuerda que perteneces a algo más grande que tu dolor." },
  { id: 316, q: "Aceptar la amabilidad de un vecino que te ayuda…", options: ["Es recibir un gesto humano sin deber nada", "Te obliga a devolver el favor", "Es peligroso siempre", "Te hace dependiente"], answer: 0, why: "Aceptar un gesto amable no crea deuda: crea comunidad." },
  { id: 317, q: "Pedir ayuda antes de tocar fondo es…", options: ["Inteligente: no hay que esperar a romperse", "Exagerar", "Débil", "Innecesario"], answer: 0, why: "No necesitas estar al límite para merecer apoyo: pedir a tiempo también es cuidarte." },
  { id: 318, q: "Tener una persona a quien llamar en un momento difícil es…", options: ["Ser dependiente", "Tener un salvavidas emocional", "Molestar a alguien", "Innecesario"], answer: 1, why: "Saber a quién llamar cuando todo se nubla te da seguridad." },
  { id: 319, q: "Tu red de apoyo puede incluir…", options: ["Solo familia", "Solo amigos", "Solo tu pareja", "Amigos, familia y profesionales"], answer: 3, why: "El apoyo más completo mezcla cariño cercano y ayuda profesional." },
  { id: 320, q: "No pedir ayuda «para no molestar a nadie»…", options: ["Es considerado", "Es lo correcto", "Te deja solo con un dolor que podrías compartir", "Te hace fuerte"], answer: 2, why: "Quien te quiere no se molesta por ayudarte: se alegra de poder estar." },
  { id: 321, q: "Hacer una lista de las personas que te apoyan sirve para…", options: ["Nada", "Presumir", "Recordar que no estás solo cuando lo olvidas", "Juzgar a otros"], answer: 2, why: "En los días oscuros, ver tu lista te recuerda que hay manos extendidas." },
  { id: 322, q: "Buscar apoyo en grupos en línea puede ayudar si…", options: ["Compartes todo sin cuidado", "Eliges espacios respetuosos y cuidas tu privacidad", "Crees todo lo que dicen", "Reemplazas a tus amigos"], answer: 1, why: "Un buen grupo en línea apoya, pero tu privacidad siempre va primero." },
  { id: 323, q: "Aceptar ayuda con gratitud…", options: ["Fortalece el vínculo con quien te apoya", "Te hace quedar mal", "Es débil", "Crea deuda eterna"], answer: 0, why: "Recibir con gratitud también es una forma de dar." },
  { id: 324, q: "Compartir tus avances con tu comunidad o grupo de apoyo…", options: ["Es presumir", "Molesta a los demás", "Es innecesario", "Inspira a otros que están empezando"], answer: 3, why: "Tu avance puede ser la esperanza de alguien que hoy está donde tú estuviste." },
  { id: 325, q: "En tu primera sesión de terapia, lo más sano es…", options: ["Contar todo de una vez", "Quedar bien con el terapeuta", "Callar lo importante", "Contar tu historia a tu ritmo"], answer: 3, why: "No hay prisa: la terapia avanza a la velocidad en que tú confías." },
  { id: 326, q: "Un buen terapeuta…", options: ["Te ayuda a ver con claridad para que decidas tú", "Te dice qué hacer", "Decide por ti", "Te da todas las respuestas"], answer: 0, why: "El terapeuta ilumina el camino, pero quien camina eres tú." },
  { id: 327, q: "Si no conectas con tu terapeuta, cambiar de profesional es…", options: ["Un fracaso", "Ser difícil", "Válido: la conexión importa", "Perder el tiempo"], answer: 2, why: "La confianza es la base de la terapia: buscar a alguien con quien conectes está bien." },
  { id: 328, q: "La terapia familiar tras una separación puede ayudar a…", options: ["Echar culpas", "Reorganizar la familia con menos dolor", "Volver a unir a la pareja", "Evitar hablar del tema"], answer: 1, why: "Toda la familia está en duelo: sanar juntos también es posible." },
  { id: 329, q: "Llevar a tus hijos con un profesional si lo necesitan tras la separación es…", options: ["Exagerar", "Cuidarlos de verdad", "Admitir que fallaste", "Innecesario"], answer: 1, why: "Buscar ayuda para tus hijos no es exagerar: es amarlos con hechos." },
  { id: 330, q: "Esperar que la terapia lo arregle todo en una sesión es…", options: ["Realista", "Lo normal", "Irreal: sanar es un proceso", "Exigir poco"], answer: 2, why: "La terapia construye cambio sesión a sesión, como sanar capa por capa." },
  { id: 331, q: "Contarle a tu familia que vas a terapia es…", options: ["Algo que necesita su permiso", "Vergonzoso", "Obligatorio", "Tu decisión: no necesitas aprobación"], answer: 3, why: "Ir a terapia es tu decisión: compartirlo es opcional, no un permiso." },
  { id: 332, q: "Un psicólogo y un psiquiatra se diferencian en que…", options: ["El psiquiatra puede recetar medicamentos y el psicólogo no", "Son lo mismo", "El psicólogo receta más", "Ninguno ayuda"], answer: 0, why: "Cada profesional tiene su rol: conocer la diferencia te ayuda a buscar la ayuda adecuada." },
  { id: 333, q: "En una familia ensamblada, los nuevos roles…", options: ["Se construyen con tiempo y paciencia", "Llegan de inmediato", "No existen", "Los impone el adulto"], answer: 0, why: "Ser familia ensamblada se construye día a día, sin apurar los vínculos." },
  { id: 334, q: "Con los hijastros, lo más sano es…", options: ["Exigir que te quieran", "Imponer tu autoridad desde el primer día", "Ignorarlos", "Ganarte su confianza con respeto y tiempo"], answer: 3, why: "El cariño de un hijastro se gana con respeto, no se exige." },
  { id: 335, q: "La nueva pareja de tu ex, para tus hijos, puede ser…", options: ["Tu enemiga siempre", "Una adulta más que los cuida, si hay respeto", "Alguien a quien atacar", "Un peligro seguro"], answer: 1, why: "Que otra persona trate bien a tus hijos no te quita tu lugar: suma cuidado." },
  { id: 336, q: "Tener reglas claras en ambas casas para los hijos…", options: ["Es imposible", "Confunde a los niños", "Les da estabilidad aunque vivan en dos casas", "No importa"], answer: 2, why: "Dos casas con reglas parecidas les dan a los niños un mundo predecible." },
  { id: 337, q: "Competir con la otra casa por el cariño de tus hijos…", options: ["Funciona", "Es divertido", "Los pone en medio de una guerra que no pidieron", "Es necesario"], answer: 2, why: "Tus hijos no son un premio: competir por su amor solo los lastima." },
  { id: 338, q: "Presentar a tus hijos a tu nueva familia ensamblada debe hacerse…", options: ["Con calma y sin presión", "De golpe", "Sin avisarles", "Solo si ellos lo exigen"], answer: 0, why: "Sin presión, los niños se acercan a su ritmo y el vínculo nace más sano." },
  { id: 339, q: "El respeto entre los adultos de una familia ensamblada…", options: ["No importa", "Es imposible", "Es solo apariencia", "Es lo que más protege a los hijos"], answer: 3, why: "Cuando los adultos se respetan, los niños crecen en paz aunque la familia sea distinta." },
  { id: 340, q: "Ser padrastro o madrastra significa…", options: ["Reemplazar al padre o la madre", "Sumar un adulto que cuida, sin ocupar el lugar de nadie", "Mandar sobre los niños", "Ser un invitado para siempre"], answer: 1, why: "Un padrastro o madrastra suma amor: no viene a reemplazar a nadie." },
  { id: 341, q: "La ansiedad es, en su origen…", options: ["Una alarma del cuerpo que intenta protegerte", "Una enfermedad que no tiene remedio", "Una señal de debilidad", "Algo que solo les pasa a otros"], answer: 0, why: "La ansiedad es una alarma: incómoda, pero su intención es cuidarte." },
  { id: 342, q: "Cuando la ansiedad sube, el cuerpo suele…", options: ["Dormirse de inmediato", "Acelerar el corazón y tensar los músculos", "Dejar de sentir", "Volverse más lento siempre"], answer: 1, why: "El cuerpo se prepara para actuar: por eso late más rápido y se tensa." },
  { id: 343, q: "Pensar una y otra vez en lo que podría salir mal es…", options: ["Planificar bien", "Ser realista", "Anticipar lo peor una y otra vez", "Tener buena memoria"], answer: 2, why: "Repetir lo peor en tu cabeza no lo previene: solo te hace sufrirlo dos veces." },
  { id: 344, q: "Si la ansiedad te despierta de noche, lo más sano es…", options: ["Revisar el celular hasta cansarte", "Forzarte a dormir a como dé lugar", "Levantarte a comer sin hambre", "Respirar despacio y aceptar que estás despierto"], answer: 3, why: "Pelear con el insomnio lo empeora: la calma vuelve cuando dejas de forcejear." },
  { id: 345, q: "Respirar más lento cuando estás ansioso ayuda porque…", options: ["Le dice a tu cuerpo que el peligro ya pasó", "Te distrae para siempre", "Elimina el problema", "Te hace olvidar todo"], answer: 0, why: "La respiración lenta es el freno natural de la alarma interna." },
  { id: 346, q: "La ansiedad antes de un cambio importante es…", options: ["Señal de que no debes hacerlo", "Normal: lo nuevo siempre inquieta", "Prueba de que vas a fallar", "Algo que debes esconder"], answer: 1, why: "Sentir nervios ante lo nuevo no significa que no puedas: significa que te importa." },
  { id: 347, q: "Cuando sientes un nudo en el estómago por nervios, ese nudo es…", options: ["Un problema grave siempre", "Hambre", "Tu cuerpo expresando la emoción", "Imaginación tuya"], answer: 2, why: "Las emociones viven también en el cuerpo: el estómago suele ser su primer aviso." },
  { id: 348, q: "Evitar siempre lo que te da ansiedad…", options: ["Te cura", "Es la mejor estrategia", "Te hace más fuerte", "Hace que el miedo crezca con el tiempo"], answer: 3, why: "Evitar alivia un momento, pero el miedo vuelve más grande la próxima vez." },
  { id: 349, q: "Cuando la ansiedad te hace imaginar el peor escenario, una pregunta útil es…", options: ["¿Qué pruebas tengo de que eso pasará?", "¿Y si todo sale mal?", "¿Por qué siempre me pasa a mí?", "¿Qué dirán los demás?"], answer: 0, why: "Preguntar por pruebas baja la ansiedad del «seguro pasa» al «tal vez no»." },
  { id: 350, q: "Si la ansiedad interfiere con tu vida diaria, lo más sano es…", options: ["Aguantar en silencio", "Buscar apoyo profesional", "Esperar a que pase sola siempre", "Esconderla de todos"], answer: 1, why: "Pedir ayuda a tiempo es cuidarte, no rendirte." },
  { id: 351, q: "La tristeza después de una pérdida es…", options: ["Una debilidad", "Algo que debes esconder", "Una respuesta natural del corazón", "Señal de que no avanzas"], answer: 2, why: "Estar triste por perder algo valioso es tan natural como respirar." },
  { id: 352, q: "Permitirte estar triste sin juzgarte…", options: ["Te hunde más", "Es perder el tiempo", "Te hace débil", "Te ayuda a que la tristeza pase más pronto"], answer: 3, why: "Lo que se permite sentir, se procesa; lo que se reprime, se queda." },
  { id: 353, q: "Un día triste en medio de tu recuperación significa…", options: ["Que sigues siendo humano", "Que volviste a cero", "Que fracasaste", "Que nunca sanarás"], answer: 0, why: "Un día gris no borra tu camino: es solo una nube pasajera." },
  { id: 354, q: "La tristeza y la depresión se diferencian en que…", options: ["Son lo mismo", "La tristeza pasa y la depresión persiste y pesa en todo", "La depresión no existe", "La tristeza es peor"], answer: 1, why: "La tristeza visita; la depresión se instala y merece apoyo profesional." },
  { id: 355, q: "Cuando estás triste, aislarte por completo…", options: ["Es la solución", "Te fortalece", "Suele hacer la tristeza más pesada", "Es lo que todos deben hacer"], answer: 2, why: "Un poco de soledad ayuda, pero el encierro total alimenta la tristeza." },
  { id: 356, q: "Escuchar música triste cuando estás triste…", options: ["Siempre empeora todo", "Está prohibido", "Es de débiles", "Puede acompañarte y ayudarte a soltar"], answer: 3, why: "A veces una canción dice lo que tú no puedes decir todavía." },
  { id: 357, q: "Decir «estoy triste» en voz alta es…", options: ["Un acto de honestidad contigo", "Una queja inútil", "Buscar lástima", "Ser negativo"], answer: 0, why: "Nombrar lo que sientes es el primer paso para atenderlo." },
  { id: 358, q: "La tristeza también puede traer…", options: ["Solo cosas malas", "Claridad sobre lo que de verdad te importa", "Nada bueno", "Puro estancamiento"], answer: 1, why: "En la tristeza descubres qué valoras y qué quieres cuidar." },
  { id: 359, q: "Si un amigo está triste, lo mejor que puedes hacer es…", options: ["Darle mil consejos", "Decirle que no llore", "Estar presente y escuchar sin juzgar", "Distraerlo a toda costa"], answer: 2, why: "Acompañar en silencio vale más que mil consejos apurados." },
  { id: 360, q: "Llorar cuando estás triste…", options: ["Es de débiles", "No sirve de nada", "Empeora todo", "Libera tensión y alivia el cuerpo"], answer: 3, why: "Llorar no es rendirse: es el cuerpo soltando lo que pesa." },
  { id: 361, q: "El enojo es una emoción que…", options: ["Avisa que algo te parece injusto o te lastimó", "Siempre es mala", "Hay que eliminar", "Solo sienten las malas personas"], answer: 0, why: "El enojo es un mensajero: te avisa que algo cruzó un límite." },
  { id: 362, q: "Explotar de enojo y decir lo primero que piensas suele…", options: ["Resolver el problema", "Hacerte sentir mejor para siempre", "Dejar heridas que luego cuestan reparar", "Ganar respeto"], answer: 2, why: "Las palabras dichas con enojo se quedan aunque pidas perdón después." },
  { id: 363, q: "Guardar el enojo sin expresarlo nunca…", options: ["Es lo más sano", "Lo acumula hasta que sale de la peor forma", "Lo hace desaparecer", "Te hace más fuerte"], answer: 1, why: "El enojo guardado no se va: se fermenta y sale cuando menos quieres." },
  { id: 364, q: "Antes de responder enojado, lo más sano es…", options: ["Responder más fuerte", "Escribir todo de inmediato", "Ignorar para siempre", "Tomarte una pausa y respirar"], answer: 3, why: "Una pausa de minutos puede salvar una relación de años." },
  { id: 365, q: "El enojo guardado en el cuerpo suele sentirse como…", options: ["Tensión en la mandíbula, el cuello o los puños", "Relajación total", "Sueño profundo", "Hambre"], answer: 0, why: "Tu cuerpo avisa antes que tu boca: aprende a leer esas señales." },
  { id: 366, q: "Decir «estoy enojado por esto» con calma es…", options: ["Debilidad", "Perder la discusión", "Expresar tu enojo sin atacar", "Ser frío"], answer: 2, why: "Puedes estar enojado y hablar con respeto al mismo tiempo." },
  { id: 367, q: "El enojo que se repite todos los días por lo mismo puede estar señalando…", options: ["Que eres una mala persona", "Una necesidad no atendida o un límite sin poner", "Que los demás son el problema siempre", "Que no tienes remedio"], answer: 1, why: "El enojo repetido es una alarma que insiste: algo necesita cambiar." },
  { id: 368, q: "Cuando el enojo te hace hablar más rápido y más fuerte, eso es…", options: ["Señal de que tienes razón", "Energía de sobra", "Buena comunicación", "Tu cuerpo en modo alerta"], answer: 3, why: "Hablar rápido y fuerte es el cuerpo acelerado: bajar el ritmo baja el enojo." },
  { id: 369, q: "El enojo y la violencia…", options: ["No son lo mismo: sentir enojo no justifica dañar", "Son exactamente iguales", "Siempre van juntos", "No se pueden separar"], answer: 0, why: "Sentir enojo es humano; dañar a alguien es una elección." },
  { id: 370, q: "Hacer ejercicio o caminar cuando estás enojado…", options: ["Empeora el enojo", "Es perder el tiempo", "Ayuda a descargar la tensión del cuerpo", "Es huir del problema"], answer: 2, why: "Mover el cuerpo baja la intensidad y te devuelve la cabeza fría." },
  { id: 371, q: "La culpa sana te dice…", options: ["Que eres mala persona", "Que algo que hiciste no va con tus valores", "Que no mereces nada", "Que debes castigarte siempre"], answer: 1, why: "La culpa sana señala una acción, no tu valor como persona." },
  { id: 372, q: "La vergüenza se diferencia de la culpa en que…", options: ["Son lo mismo", "La vergüenza es más leve", "La culpa es peor siempre", "La vergüenza ataca quién eres, la culpa lo que hiciste"], answer: 3, why: "«Hice algo mal» se repara; «soy malo» se siente sin salida, y no es verdad." },
  { id: 373, q: "Sentir culpa por descansar cuando otros trabajan es…", options: ["Una creencia aprendida, no una verdad", "Prueba de que eres flojo", "Lo correcto", "Señal de egoísmo"], answer: 0, why: "Descansar no es robarle nada a nadie: es parte de cuidarte." },
  { id: 374, q: "Cuando la culpa es exagerada, suele…", options: ["Ayudarte a crecer", "Ser precisa siempre", "Hacerte responsable hasta de lo que no controlas", "Desaparecer sola"], answer: 2, why: "Cargar culpas ajenas pesa tanto como cargar las propias." },
  { id: 375, q: "Reparar un error por el que sientes culpa…", options: ["Es imposible", "Alivia la culpa mejor que castigarte", "No sirve", "Empeora todo"], answer: 1, why: "Reparar convierte la culpa en aprendizaje y en paz." },
  { id: 376, q: "La vergüenza de hablar de lo que sientes suele venir de…", options: ["Ser débil", "No tener nada que decir", "Ser raro", "Creer que te van a juzgar o rechazar"], answer: 3, why: "El miedo al juicio cierra bocas; un espacio seguro las abre." },
  { id: 377, q: "Sentir vergüenza por llorar frente a otros es…", options: ["Común, pero llorar no tiene nada de vergonzoso", "Prueba de debilidad", "Razón para no llorar nunca", "Algo que solo te pasa a ti"], answer: 0, why: "Llorar frente a otros es humano, no vergonzoso." },
  { id: 378, q: "La culpa por haber terminado una relación que te hacía daño…", options: ["Significa que debiste quedarte", "Es prueba de amor", "Es normal, y no significa que decidiste mal", "Dura para siempre"], answer: 2, why: "Puedes sentir culpa y a la vez saber que elegiste cuidarte." },
  { id: 379, q: "Compararte con otros y sentirte menos suele alimentar…", options: ["Motivación sana", "Vergüenza y culpa sin fundamento", "Alegría", "Confianza"], answer: 1, why: "Compararte con la mejor versión de otros solo te hace sentir insuficiente." },
  { id: 380, q: "Hablar de tu vergüenza en un espacio seguro…", options: ["La hace más grande", "Es peligroso siempre", "No cambia nada", "Le quita fuerza y te libera"], answer: 3, why: "La vergüenza vive en secreto: al nombrarla, pierde poder." },
  { id: 381, q: "El miedo, en su función original, sirve para…", options: ["Alertarte de un posible peligro", "Frenarte siempre", "Hacerte débil", "Controlar tu vida"], answer: 0, why: "El miedo es un guardián antiguo: avisa, aunque a veces exagera." },
  { id: 382, q: "Tener miedo de volver a intentarlo después de una caída es…", options: ["Prueba de que no puedes", "Señal de fracaso", "Algo raro", "Normal: el corazón aprendió a cuidarse"], answer: 3, why: "El miedo después de una caída es tu corazón pidiendo ir con más calma." },
  { id: 383, q: "La valentía significa…", options: ["No sentir miedo nunca", "Actuar aunque sientas miedo", "Ser temerario", "Ignorar el peligro"], answer: 1, why: "Valiente no es quien no teme: es quien avanza con miedo y todo." },
  { id: 384, q: "El miedo al futuro desconocido se alimenta de…", options: ["La calma", "La información clara", "Imaginar lo peor sin pruebas", "El descanso"], answer: 2, why: "El futuro no se conoce imaginando desastres: se construye paso a paso." },
  { id: 385, q: "Cuando el miedo te paraliza, un primer paso sano es…", options: ["Hacer algo muy pequeño y concreto", "Esperar a no sentir nada", "Huir para siempre", "Exigirte hacerlo todo de golpe"], answer: 0, why: "Un paso pequeño rompe la parálisis mejor que un plan perfecto." },
  { id: 386, q: "El miedo a equivocarte puede hacerte…", options: ["Más perfecto", "Más feliz", "Más libre", "Quedarte quieto y no intentar nada"], answer: 3, why: "El miedo a fallar cobra caro: te cobra los intentos." },
  { id: 387, q: "El miedo a que algo bueno se acabe puede hacerte…", options: ["Disfrutarlo más", "Sabotearlo antes de que termine", "Valorarlo mejor", "Dormir tranquilo"], answer: 1, why: "A veces rompemos lo bueno por miedo a perderlo: disfrutarlo es el antídoto." },
  { id: 388, q: "El cuerpo con miedo suele…", options: ["Relajarse", "Dormirse", "Tensarse, sudar o acelerar el corazón", "No sentir nada"], answer: 2, why: "El cuerpo reacciona antes que la mente: esas señales son tu alarma." },
  { id: 389, q: "El miedo a ser juzgado puede impedirte…", options: ["Ser tú mismo frente a otros", "Dormir bien siempre", "Comer", "Reírte solo"], answer: 0, why: "El miedo al juicio ajeno te hace esconder justo lo que te hace único." },
  { id: 390, q: "Afrontar un miedo poco a poco, en pasos pequeños, se llama…", options: ["Huida", "Negación", "Suerte", "Exposición gradual"], answer: 3, why: "Acercarte de a poco le enseña a tu cuerpo que no hay peligro real." },
  { id: 391, q: "Los celos y la envidia se diferencian en que…", options: ["Son lo mismo", "Los celos temen perder algo, la envidia desea lo ajeno", "La envidia es peor", "Los celos son amor"], answer: 1, why: "Celos: miedo a perder. Envidia: deseo de tener. Entenderlo ayuda a atender cada uno." },
  { id: 392, q: "Sentir celos de vez en cuando es…", options: ["Prueba de amor", "Motivo para controlar", "Humano, si no controla tus actos", "Señal de que debes terminar"], answer: 2, why: "Sentir celos no te hace mala persona: lo que haces con ellos sí importa." },
  { id: 393, q: "Cuando sientes celos, lo más sano es…", options: ["Preguntarte qué inseguridad te están mostrando", "Revisar todo de inmediato", "Acusar sin pruebas", "Guardarlo y explotar después"], answer: 0, why: "Los celos suelen hablar más de tus miedos que de la otra persona." },
  { id: 394, q: "Hablar de tus celos con tu pareja sin acusar…", options: ["Es perder", "Empeora todo", "Es de débiles", "Abre la puerta a la confianza"], answer: 3, why: "Decir «me siento inseguro» une más que decir «tú me engañas»." },
  { id: 395, q: "La envidia puede ser una pista de…", options: ["Que eres mala persona", "Algo que deseas y aún no tienes", "Que odias a todos", "Que no tienes remedio"], answer: 1, why: "La envidia señala un deseo: escucharla te muestra hacia dónde quieres ir." },
  { id: 396, q: "Ver la vida perfecta de otros en redes y sentir envidia es…", options: ["Prueba de fracaso", "Algo raro", "Común, porque ves solo lo mejor de otros", "Motivo para borrarte de todo"], answer: 2, why: "Comparas tu detrás de cámaras con el escenario de otros: no es justo contigo." },
  { id: 397, q: "Convertir la envidia en inspiración significa…", options: ["Usarla como mapa de lo que quieres lograr", "Copiar a la otra persona", "Odiarla en silencio", "Negar que la sientes"], answer: 0, why: "La envidia bien mirada se vuelve brújula, no veneno." },
  { id: 398, q: "Los celos en una amistad pueden aparecer cuando…", options: ["Todo va perfecto", "No hay cariño", "Nunca pasa", "Sientes que te están reemplazando"], answer: 3, why: "Los celos también viven en la amistad: hablan de cuánto te importa ese vínculo." },
  { id: 399, q: "Controlar a tu pareja para calmar los celos…", options: ["Funciona para siempre", "Alivia un momento y luego pide más control", "Es amor", "Genera confianza"], answer: 1, why: "El control nunca calma del todo: cada revisión pide la siguiente." },
  { id: 400, q: "Alegrarte por el logro de alguien que envidiabas es…", options: ["Fingir", "Imposible", "Señal de que estás creciendo por dentro", "Debilidad"], answer: 2, why: "Celebrar lo ajeno sin sentirte menos es libertad emocional." },
  { id: 401, q: "Estar solo y sentirse solo…", options: ["No es lo mismo: puedes estar acompañado y sentirte solo", "Es exactamente igual", "Nunca pasa", "Es lo mismo siempre"], answer: 0, why: "La soledad es una sensación, no un conteo de personas." },
  { id: 402, q: "La soledad elegida, como un rato para ti, puede ser…", options: ["Peligrosa", "Reparadora y necesaria", "Triste siempre", "Egoísta"], answer: 1, why: "Un rato a solas por elección recarga; impuesto, pesa." },
  { id: 403, q: "Sentirte solo en una reunión llena de gente suele pasar cuando…", options: ["Eres raro", "No te gusta nadie", "No te sientes visto ni conectado", "Eres antisocial"], answer: 2, why: "La conexión no es estar rodeado: es sentirte visto." },
  { id: 404, q: "Cuando la soledad pesa mucho, un paso sano es…", options: ["Encerrarte más", "Esperar a que pase sola", "Llenar todo de ruido", "Buscar una conversación real con alguien"], answer: 3, why: "Una conversación de verdad alivia más que mil distracciones." },
  { id: 405, q: "La nostalgia es…", options: ["Añorar un tiempo pasado, con cariño y algo de tristeza", "Vivir en el pasado", "Una enfermedad", "Debilidad"], answer: 0, why: "La nostalgia mezcla cariño y tristeza: es el corazón visitando recuerdos." },
  { id: 406, q: "La nostalgia tiende a…", options: ["Recordar todo tal cual fue", "Idealizar el pasado y olvidar lo difícil", "Borrar los recuerdos", "Ser siempre precisa"], answer: 1, why: "La nostalgia pinta el pasado más bonito de lo que fue: mírala con cariño y con calma." },
  { id: 407, q: "Extrañar los buenos momentos de una relación que terminó…", options: ["Significa que debes volver", "Es un error", "Es normal: lo bueno también existió", "Es no haber sanado"], answer: 2, why: "Puedes extrañar lo bonito y a la vez saber que la decisión fue correcta." },
  { id: 408, q: "Usar la nostalgia para agradecer lo vivido, en vez de quedarte en ella, es…", options: ["Imposible", "Negar el dolor", "Perder el tiempo", "Una forma sana de honrar tu historia"], answer: 3, why: "Agradecer lo vivido te deja llevarte lo bueno sin quedarte atrapado." },
  { id: 409, q: "Una rutina de contacto con otros (llamar, salir, saludar)…", options: ["Ayuda a que la soledad pese menos", "Es molestar a otros", "No sirve", "Es dependencia"], answer: 0, why: "Los pequeños contactos diarios son puentes contra la soledad." },
  { id: 410, q: "Aprender a disfrutar tu propia compañía…", options: ["Te aísla", "Te hace menos dependiente de la aprobación ajena", "Es egoísmo", "Es imposible"], answer: 1, why: "Caerte bien a ti mismo es la compañía que nunca te abandona." },
  { id: 411, q: "Respirar profundo y lento le envía a tu cuerpo el mensaje de…", options: ["Peligro", "Alerta máxima", "Calma: no hay emergencia", "Dormir de inmediato"], answer: 2, why: "La respiración lenta es el interruptor de calma más rápido que tienes." },
  { id: 412, q: "Una técnica simple de respiración es…", options: ["Respirar lo más rápido posible", "Aguantar el aire mucho tiempo", "Respirar solo por la boca", "Inhalar en 4, sostener en 4 y exhalar en 4"], answer: 3, why: "Contar la respiración le da a tu mente algo tranquilo en qué apoyarse." },
  { id: 413, q: "Cuando estás tenso, los hombros suelen…", options: ["Subirse hacia las orejas sin que lo notes", "Relajarse solos", "Dormirse", "No cambiar"], answer: 0, why: "Los hombros guardan tensión: bajarlos a propósito ya es un alivio." },
  { id: 414, q: "Notar dónde sientes la emoción en el cuerpo se llama…", options: ["Imaginar cosas", "Escuchar a tu cuerpo", "Exagerar", "Perder el tiempo"], answer: 1, why: "Tu cuerpo habla: el pecho, el estómago y la garganta suelen avisar primero." },
  { id: 415, q: "Un cuerpo cansado y sin dormir…", options: ["Maneja mejor las emociones", "No afecta nada", "Reacciona con más intensidad a todo", "Se vuelve más paciente"], answer: 2, why: "Dormir poco deja las emociones a flor de piel: el descanso también es regulación." },
  { id: 416, q: "Apretar y soltar los músculos, grupo por grupo, ayuda a…", options: ["Cansarte más", "Doler más", "Perder tiempo", "Soltar la tensión acumulada"], answer: 3, why: "Tensar y soltar le enseña al cuerpo la diferencia entre tensión y calma." },
  { id: 417, q: "Caminar despacio y prestando atención a tus pasos…", options: ["Calma la mente y baja la tensión", "Es perder el tiempo", "Empeora el ánimo", "Solo sirve para atletas"], answer: 0, why: "Caminar con atención es una pausa que mueve el cuerpo y aquieta la mente." },
  { id: 418, q: "El estómago revuelto antes de algo importante es…", options: ["Una enfermedad", "Tu cuerpo reaccionando a la emoción", "Hambre siempre", "Imaginación"], answer: 1, why: "El estómago y las emociones están conectados: lo que sientes, lo siente tu cuerpo." },
  { id: 419, q: "Beber agua y comer a tus horas cuando estás mal emocionalmente…", options: ["No importa", "Empeora todo", "Sostiene a tu cuerpo para manejar lo que sientes", "Es egoísmo"], answer: 2, why: "Un cuerpo cuidado aguanta mejor las tormentas emocionales." },
  { id: 420, q: "Si notas que respiras muy rápido por nervios, lo primero es…", options: ["Respirar aún más rápido", "Ignorarlo", "Contener el aire", "Alargar la exhalación, más lenta que la inhalación"], answer: 3, why: "Exhalar lento es lo que más calma: ahí está el freno de la ansiedad." },
  { id: 421, q: "Ponerle nombre a lo que sientes («esto es tristeza»)…", options: ["Reduce su intensidad y te ayuda a manejarlo", "Lo empeora", "No cambia nada", "Es de débiles"], answer: 0, why: "Nombrar la emoción le pone un borde: deja de ser una ola sin nombre." },
  { id: 422, q: "Decir «estoy enojado» en vez de «tú me enojas»…", options: ["Es lo mismo", "Es más débil", "Te hace dueño de tu emoción sin culpar al otro", "Es mentir"], answer: 2, why: "Hablar en primera persona te devuelve el control de lo que sientes." },
  { id: 423, q: "Antes de responder un mensaje que te alteró, esperar unos minutos…", options: ["Es perder", "Te permite responder desde la calma y no desde el impulso", "Empeora todo", "Es cobardía"], answer: 1, why: "Un mensaje esperado se escribe mejor que uno lanzado con enojo." },
  { id: 424, q: "Regular una emoción significa…", options: ["No sentirla nunca", "Esconderla", "Negarla", "Sentirla y elegir cómo responder a ella"], answer: 3, why: "Regular no es apagar: es sentir sin que la emoción maneje el volante." },
  { id: 425, q: "Preguntarte «¿qué necesito ahora mismo?» cuando estás mal…", options: ["Te ayuda a cuidarte en vez de reaccionar", "Es egoísmo", "No sirve", "Es perder tiempo"], answer: 0, why: "Esa pregunta cambia el modo: de reaccionar a cuidarte." },
  { id: 426, q: "Medir tu emoción del 1 al 10 te ayuda a…", options: ["Exagerar", "Ignorarla", "Saber si necesitas una pausa o puedes seguir", "Competir"], answer: 2, why: "Ponerle número a lo que sientes te muestra si es una ola o un tsunami." },
  { id: 427, q: "Cuando estás cansado, con hambre o abrumado, reaccionas…", options: ["Mejor que nunca", "Con menos paciencia y más intensidad", "Igual siempre", "Con más calma"], answer: 1, why: "El cuerpo agotado no regula igual: atiende primero lo básico." },
  { id: 428, q: "Contar hasta diez antes de responder con enojo funciona porque…", options: ["Es magia", "El otro se aburre", "No funciona nunca", "Le da tiempo a tu mente de bajar la intensidad"], answer: 3, why: "Diez segundos bastan para que la primera reacción pierda fuerza." },
  { id: 429, q: "Escribir lo que sientes antes de hablarlo con alguien…", options: ["Te ayuda a ordenar ideas y bajar la intensidad", "Es perder el tiempo", "Empeora todo", "Es de niños"], answer: 0, why: "Escribir primero es como ensayar: llegas más claro a la conversación." },
  { id: 430, q: "Si una emoción te desborda, alejarte un momento del lugar…", options: ["Es huir siempre", "Es de cobardes", "Es una pausa sana para recuperar el control", "Empeora todo"], answer: 2, why: "Alejarte un rato no es huir: es volver con la cabeza más clara." },
  { id: 431, q: "Prestar atención al momento presente, sin juzgar lo que sientes, se llama…", options: ["Distraerse", "Atención plena", "Ignorar el problema", "Dormir despierto"], answer: 1, why: "Estar presente es mirar lo que pasa dentro de ti sin pelear con ello." },
  { id: 432, q: "Observar un pensamiento sin creerle de inmediato…", options: ["Es imposible", "Es negarlo", "Es perder tiempo", "Te da libertad frente a lo que piensas"], answer: 3, why: "Un pensamiento es solo un pensamiento: no todo lo que piensas es verdad." },
  { id: 433, q: "Nombrar 5 cosas que ves, 4 que tocas y 3 que escuchas sirve para…", options: ["Volver al presente cuando la mente se dispara", "Distraerte para siempre", "Perder tiempo", "Dormir"], answer: 0, why: "Los sentidos son anclas: te traen de vuelta al aquí y ahora." },
  { id: 434, q: "La atención plena NO es…", options: ["Observar sin juzgar", "Respirar con calma", "Dejar la mente en blanco para siempre", "Estar presente"], answer: 2, why: "No se trata de vaciar la mente: se trata de mirarla con calma." },
  { id: 435, q: "Sentir alivio después de llorar mucho es…", options: ["Raro", "Señal de que el cuerpo soltó tensión", "Debilidad", "Fingir"], answer: 1, why: "El alivio tras el llanto es el cuerpo volviendo a su calma." },
  { id: 436, q: "La esperanza realista es…", options: ["Creer que todo saldrá perfecto", "Negar el dolor", "Esperar sin hacer nada", "Creer que puedes mejorar paso a paso, aunque hoy duela"], answer: 3, why: "La esperanza no niega el dolor: cree que el dolor no es el final." },
  { id: 437, q: "Un pequeño momento de calma en un día difícil…", options: ["Vale oro: muestra que la calma sigue disponible", "No cuenta", "Es suerte", "No sirve"], answer: 0, why: "Un respiro de calma en un día gris es una prueba de que puedes volver a ella." },
  { id: 438, q: "Practicar la atención plena unos minutos al día…", options: ["Es perder tiempo", "Solo sirve para otros", "Entrena tu mente como el ejercicio entrena el cuerpo", "Es imposible"], answer: 2, why: "La calma también se entrena: unos minutos al día hacen la diferencia." },
  { id: 439, q: "Cuando sientes alivio al soltar algo que te pesaba, ese alivio…", options: ["Es egoísmo", "Es tu cuerpo agradeciendo la carga que soltaste", "Dura nada", "Es culpa disfrazada"], answer: 1, why: "Soltar pesa al principio y alivia después: el alivio confirma que elegiste bien." },
  { id: 440, q: "La esperanza se alimenta de…", options: ["Ignorar la realidad", "Promesas vacías", "Quedarte quieto", "Pequeños avances que vas notando"], answer: 3, why: "Cada paso pequeño que notas es leña para la esperanza." },
  { id: 441, q: "Volver a salir después de una ruptura es más sano cuando…", options: ["Lo haces para olvidar rápido", "Alguien te presiona para que salgas", "Te sientes listo y no buscas huir del dolor", "Quieres darle celos a tu ex"], answer: 2, why: "Salir por ti, y no por huir, hace que la experiencia sea tuya y no una reacción." },
  { id: 442, q: "Conocer gente nueva después de una ruptura ayuda porque…", options: ["Te distrae para siempre", "Te recuerda que el mundo es más grande que una historia", "Borra el pasado", "Te obliga a tener pareja"], answer: 1, why: "Gente nueva trae aire nuevo: tu vida no se quedó en una sola persona." },
  { id: 443, q: "Si te da nervios volver a socializar, lo más sano es…", options: ["Empezar con planes pequeños y cómodos", "Encerrarte hasta que pase", "Fingir que no sientes nada", "Evitar a todos para siempre"], answer: 0, why: "Pasos pequeños y cómodos devuelven la confianza sin forzarte." },
  { id: 444, q: "Un buen primer paso para conocer gente es…", options: ["Quedarte esperando en casa", "Buscar pareja de inmediato", "Cambiar tu forma de ser", "Unirte a una actividad que te guste"], answer: 3, why: "Hacer lo que te gusta te cruza con gente afín sin presión." },
  { id: 445, q: "Cuando conoces a alguien nuevo, lo más sano es…", options: ["Contar toda tu historia el primer día", "Compararlo con tu ex en voz alta", "Decidir de inmediato si es «la persona»", "Ir conociéndolo poco a poco"], answer: 3, why: "Conocer poco a poco deja que la verdad aparezca sin prisa." },
  { id: 446, q: "Sentir nervios al conocer gente nueva es…", options: ["Normal: estás saliendo de tu zona cómoda", "Señal de que no estás listo", "Un problema grave", "Razón para rendirte"], answer: 0, why: "Los nervios no son un freno: son la señal de que estás creciendo." },
  { id: 447, q: "Si una salida no sale como esperabas, lo más sano es…", options: ["No salir nunca más", "Tomarlo como práctica y seguir intentando", "Culparte de todo", "Decir que nadie vale la pena"], answer: 1, why: "Una salida regular no define tu futuro: es solo práctica." },
  { id: 448, q: "Conocer gente sin buscar pareja de inmediato te permite…", options: ["Perder el tiempo", "Quedarte solo", "Disfrutar la compañía sin presión", "Evitar el amor"], answer: 2, why: "Sin la presión de buscar algo, la conexión llega más natural." },
  { id: 449, q: "Tu círculo social después de una ruptura…", options: ["Debe quedarse igual", "Puede crecer con personas nuevas", "Ya no importa", "Solo debe ser tu familia"], answer: 1, why: "Un círculo que crece te sostiene mejor que uno que se encoge." },
  { id: 450, q: "Si te invitan a un plan y no tienes ganas, lo más sano es…", options: ["Ir siempre aunque no quieras", "Inventar una excusa dramática", "Decir que no sin culpa esta vez", "Aceptar y quejarte todo el rato"], answer: 2, why: "Decir que no cuando no tienes ganas también es cuidarte." },
  { id: 451, q: "Volver a salir significa…", options: ["Que ya olvidaste todo", "Que el dolor desapareció", "Que estás listo para casarte", "Que estás abriendo una puerta nueva"], answer: 3, why: "Salir es abrir una puerta, no borrar lo que viviste." },
  { id: 452, q: "La mejor actitud para conocer gente nueva es…", options: ["Curiosidad y calma, sin expectativas rígidas", "Esperar lo peor", "Buscar a alguien igual a tu ex", "Juzgar rápido"], answer: 0, why: "La curiosidad sin prisa deja que las personas te sorprendan." },
  { id: 453, q: "En una primera cita, lo más importante es…", options: ["Observar cómo te trata y cómo te sientes", "Impresionar a toda costa", "Hablar solo de tu ex", "Decidir si es para siempre"], answer: 0, why: "La primera cita es para observar, no para decidir tu futuro." },
  { id: 454, q: "Al conocer a alguien por internet, lo más seguro es…", options: ["Darle tu dirección de inmediato", "Verlo en un lugar privado", "Compartir tus claves", "Quedar en un lugar público y avisar a alguien"], answer: 3, why: "Tu seguridad va primero: lugar público y alguien que sepa dónde estás." },
  { id: 455, q: "Una buena pregunta para conocer a alguien es…", options: ["¿Cuánto ganas?", "¿Por qué terminaste con tu ex?", "¿Qué te gusta hacer en tu tiempo libre?", "¿Cuándo nos casamos?"], answer: 2, why: "Preguntar por lo que le gusta abre una conversación real." },
  { id: 456, q: "Si en una cita no sientes química, lo más sano es…", options: ["Fingir interés por lástima", "Agradecer y ser honesto con amabilidad", "Desaparecer sin decir nada", "Seguir por compromiso"], answer: 1, why: "Ser honesto con amabilidad respeta tu tiempo y el del otro." },
  { id: 457, q: "Hablar de tu ex en la primera cita…", options: ["Es obligatorio", "Es la mejor forma de conectar", "Mejor dejarlo para más adelante, cuando haya confianza", "Debe ocupar toda la conversación"], answer: 2, why: "Tu historia merece contarse con calma, no como presentación." },
  { id: 458, q: "Ser tú mismo en una cita es importante porque…", options: ["Así te quieren por quien eres de verdad", "Así impresionas más", "Así evitas preguntas", "Así no tienes que esforzarte"], answer: 0, why: "Fingir cansa: ser tú atrae a quien te quiere de verdad." },
  { id: 459, q: "Si una cita sale bien, lo más sano es…", options: ["Planear la boda", "Escribir cien mensajes seguidos", "Ignorarlo para parecer interesante", "Disfrutarlo y dejar que siga fluyendo"], answer: 3, why: "Lo bueno no necesita prisa: déjalo crecer a su ritmo." },
  { id: 460, q: "Una señal de alerta en una cita es que la persona…", options: ["Sea puntual", "Te presione para decidir rápido o te falte el respeto", "Pregunte por tus gustos", "Escuche con atención"], answer: 1, why: "La presión y la falta de respeto en la primera cita no mejoran después." },
  { id: 461, q: "Ir a una segunda cita tiene sentido cuando…", options: ["Te sientes obligado", "Te sentiste cómodo y quieres conocer más", "Tus amigos insisten", "No tienes nada mejor que hacer"], answer: 1, why: "La segunda cita se elige por ganas, no por obligación." },
  { id: 462, q: "En las citas, tener expectativas realistas significa…", options: ["Esperar perfección", "No esperar nada de nadie", "Buscar a alguien sin defectos", "Conocer sin exigir un cuento perfecto"], answer: 3, why: "Nadie es perfecto: conocer con calma deja ver a la persona real." },
  { id: 463, q: "Si te cancelan una cita con respeto y reprograman, lo más sano es…", options: ["Entender que a veces pasan imprevistos", "Enojarte para siempre", "Asumir que te rechazan", "Dejar de hablarle"], answer: 0, why: "Un imprevisto con respeto no es un rechazo." },
  { id: 464, q: "El mejor momento para una cita es cuando…", options: ["Estás enojado", "Quieres olvidar a alguien", "Tienes ganas genuinas de conocer a alguien", "Te sientes solo y desesperado"], answer: 2, why: "Salir con ganas genuinas cambia por completo la experiencia." },
  { id: 465, q: "Una segunda oportunidad funciona solo si…", options: ["El tiempo pasó", "Uno de los dos lo pide mucho", "Vuelven a lo mismo de antes", "Algo cambió de verdad en los dos"], answer: 3, why: "Volver a lo mismo da el mismo resultado: el cambio real es la base." },
  { id: 466, q: "Dar una segunda oportunidad significa…", options: ["Borrar el pasado", "Abrir una puerta nueva con acuerdos nuevos", "Perdonar sin hablar", "Volver a lo mismo"], answer: 1, why: "Una segunda oportunidad es un comienzo nuevo, no una repetición." },
  { id: 467, q: "Antes de dar una segunda oportunidad, lo más sano es…", options: ["Decidir en un impulso", "Hacerlo por lástima", "Preguntarte si confías y si hubo cambios reales", "Volver por miedo a estar solo"], answer: 2, why: "La pregunta clave no es si lo quieres, sino si algo cambió de verdad." },
  { id: 468, q: "Una señal de que una segunda oportunidad va en serio es…", options: ["Hechos constantes, no solo promesas", "Palabras bonitas", "Regalos caros", "Celos"], answer: 0, why: "Las promesas se dicen fácil: los hechos se sostienen en el tiempo." },
  { id: 469, q: "Si decides NO dar una segunda oportunidad, eso es…", options: ["Válido: no estás obligado a volver", "Egoísmo", "Falta de amor", "Rencor"], answer: 0, why: "Decir que no también es una decisión sana y respetable." },
  { id: 470, q: "El miedo a que se repita lo mismo en una segunda oportunidad…", options: ["Desaparece solo", "Es señal de que no debes volver", "Se atiende con acuerdos claros y tiempo", "Se ignora"], answer: 2, why: "El miedo se calma con hechos y acuerdos, no con promesas." },
  { id: 471, q: "Una segunda oportunidad contigo mismo significa…", options: ["Castigarte por el pasado", "Darte permiso de empezar de nuevo sin culpa", "Olvidar todo", "Repetir lo mismo"], answer: 1, why: "También mereces empezar de nuevo contigo, sin cargar culpas viejas." },
  { id: 472, q: "Si la segunda oportunidad no funciona, lo más sano es…", options: ["Culparte para siempre", "Decir que el amor no existe", "Intentarlo una tercera vez igual", "Aceptarlo, aprender y seguir adelante"], answer: 3, why: "Que no funcione no es un fracaso: es una respuesta clara." },
  { id: 473, q: "Una reconciliación sana requiere que…", options: ["Uno perdone y el otro no", "Todo vuelva a ser como antes", "Los dos quieran y los dos cambien algo", "Se olvide lo que pasó"], answer: 2, why: "Reconciliarse es trabajo de dos, no de uno solo." },
  { id: 474, q: "Reconciliarse no significa…", options: ["Hablar de lo que pasó", "Poner acuerdos nuevos", "Cambiar conductas", "Hacer como si nada hubiera pasado"], answer: 3, why: "Hacer como si nada deja la herida abierta por dentro." },
  { id: 475, q: "Buscar apoyo profesional para reconciliarse es…", options: ["Señal de fracaso", "Una ayuda válida para comunicarse mejor", "Solo para casos graves", "Perder el tiempo"], answer: 1, why: "Una guía externa ayuda a hablar de lo difícil sin pelear." },
  { id: 476, q: "Después de una reconciliación, la confianza vuelve…", options: ["Con hechos repetidos en el tiempo", "De un día para otro", "Con una disculpa", "Con control total"], answer: 0, why: "La confianza se reconstruye día a día, con hechos." },
  { id: 477, q: "Si después de reconciliarse vuelve a pasar lo mismo, lo más sano es…", options: ["Perdonar sin hablar", "Poner un límite claro y decidir con calma", "Aguantar en silencio", "Gritar más fuerte"], answer: 1, why: "Repetir lo mismo después de reconciliarse es información: decide con calma." },
  { id: 478, q: "Reconciliarse con un amigo o familiar requiere…", options: ["Hablar con honestidad y escuchar al otro", "Tener la razón", "Esperar a que el otro ceda", "Olvidar sin hablar"], answer: 0, why: "La reconciliación empieza escuchando, no ganando." },
  { id: 479, q: "Perdonar en una reconciliación implica…", options: ["Justificar el daño", "Volver a confiar de inmediato", "Borrar el recuerdo", "Soltar el rencor y cuidar que no se repita"], answer: 3, why: "Perdonar es soltar la carga y a la vez cuidar que no vuelva a pasar." },
  { id: 480, q: "Una reconciliación sana se nota porque…", options: ["Nunca más discuten", "Uno manda siempre", "Pueden hablar de lo difícil sin destruirse", "Todo es perfecto"], answer: 2, why: "Hablar de lo difícil sin destruirse es la mejor señal de que sanó." },
  { id: 481, q: "Empezar una relación nueva con calma significa…", options: ["No sentir nada", "Ocultar lo que sientes", "Esperar años", "Conocerse sin correr y sin forzar etiquetas"], answer: 3, why: "Ir con calma deja que la relación crezca sobre algo real." },
  { id: 482, q: "Comparar a tu nueva pareja con tu ex…", options: ["Ayuda a elegir mejor", "Es justo", "Es injusto: cada persona es distinta", "Es necesario"], answer: 2, why: "Comparar pone a alguien nuevo a competir con un recuerdo." },
  { id: 483, q: "Hablar de expectativas al inicio de una relación…", options: ["Evita malentendidos y alinea lo que ambos quieren", "Arruina la magia", "Es innecesario", "Presiona al otro"], answer: 0, why: "Saber qué quiere cada uno evita dolores que se pudieron prevenir." },
  { id: 484, q: "Si extrañas a tu ex estando con alguien nuevo, lo más sano es…", options: ["Ocultarlo y seguir", "Reconocerlo, procesarlo y no usar a la nueva persona para olvidar", "Volver con tu ex de inmediato", "Terminar sin hablar"], answer: 1, why: "Extrañar no te hace mala persona: usar a alguien para olvidar, sí daña." },
  { id: 485, q: "Presentar a tu nueva pareja a tus amigos…", options: ["Es un paso natural cuando hay confianza", "Debe hacerse el primer día", "Es obligatorio", "Hay que evitarlo siempre"], answer: 0, why: "Presentar a alguien que importa se hace cuando hay confianza, sin prisa." },
  { id: 486, q: "La confianza en una relación nueva se construye…", options: ["Con promesas grandes", "Con coherencia entre lo que se dice y lo que se hace", "Con control", "Con celos"], answer: 1, why: "La coherencia diaria construye más confianza que mil promesas." },
  { id: 487, q: "Crear rutinas nuevas con tu pareja ayuda porque…", options: ["Borra el pasado", "Es obligación", "Construye recuerdos propios de los dos", "Evita hablar"], answer: 2, why: "Los recuerdos propios hacen que la relación sea de ustedes, no una copia." },
  { id: 488, q: "Ser honesto sobre tu proceso de sanación con alguien nuevo…", options: ["Te hace débil", "Asusta siempre", "Es innecesario", "Genera confianza y comprensión"], answer: 3, why: "Contar dónde estás permite que el otro te acompañe de verdad." },
  { id: 489, q: "Ponerle una etiqueta a la relación antes de tiempo…", options: ["Siempre ayuda", "Es lo correcto", "Puede presionar algo que aún está creciendo", "Es obligatorio"], answer: 2, why: "Las etiquetas llegan cuando la relación ya tiene forma." },
  { id: 490, q: "Si tu nueva pareja te pide ir más lento, lo más sano es…", options: ["Presionarla", "Respetar su ritmo sin tomarlo como rechazo", "Enojarte", "Terminar de inmediato"], answer: 1, why: "Ir más lento no es rechazo: es cuidado." },
  { id: 491, q: "Disfrutar la etapa de conocer a alguien significa…", options: ["No pensar en nada", "Vivir solo el presente sin cuidado", "Evitar compromiso para siempre", "Vivir el presente sin correr hacia el futuro"], answer: 3, why: "Cada etapa tiene su encanto: correr te hace perderlo." },
  { id: 492, q: "Una relación nueva es sana cuando…", options: ["Puedes ser tú sin miedo y hay respeto mutuo", "Todo es intenso desde el primer día", "No hay desacuerdos", "Uno decide todo"], answer: 0, why: "Ser tú sin miedo y con respeto es la base de lo sano." },
  { id: 493, q: "Sentirte cómodo en silencio con tu pareja es…", options: ["Aburrimiento", "Falta de amor", "Un problema", "Señal de intimidad y confianza"], answer: 3, why: "Estar bien en silencio juntos dice más que mil palabras." },
  { id: 494, q: "Hablar de lo que te incomoda en la intimidad es…", options: ["Necesario: el respeto también vive ahí", "Vergonzoso y mejor callarlo", "Falta de amor", "Innecesario"], answer: 0, why: "Decir lo que te incomoda cuida la confianza entre los dos." },
  { id: 495, q: "El compromiso en pareja es…", options: ["Una cárcel", "Control", "Una decisión diaria de cuidarse y elegirse", "Una obligación"], answer: 2, why: "El compromiso no se firma una vez: se elige todos los días." },
  { id: 496, q: "Mostrarte vulnerable con tu pareja…", options: ["Es debilidad", "Es confianza: dejas ver quién eres de verdad", "Es peligroso siempre", "Es manipulación"], answer: 1, why: "La vulnerabilidad con la persona correcta fortalece el vínculo." },
  { id: 497, q: "Respetar los tiempos del otro en la intimidad significa…", options: ["Presionar", "Esperar sin enojo a que el otro esté listo", "Ignorar", "Exigir"], answer: 1, why: "Respetar los tiempos del otro es cuidar la confianza." },
  { id: 498, q: "Hablar del futuro juntos (planes, sueños)…", options: ["Presiona", "Es aburrido", "Acerca: soñar juntos también es intimidad", "Es solo para casados"], answer: 2, why: "Soñar juntos une tanto como vivir el presente." },
  { id: 499, q: "El compromiso contigo mismo significa…", options: ["Cumplir lo que te prometes, como cumplirías con alguien más", "Exigirte perfección", "No necesitar a nadie", "Ponerte siempre último"], answer: 0, why: "Cumplirte a ti construye la confianza más importante: la tuya." },
  { id: 500, q: "Una muestra de afecto diaria y sincera…", options: ["Es cursi", "Cansa", "Es obligación", "Mantiene vivo el cariño"], answer: 3, why: "El cariño se alimenta de gestos pequeños y constantes." },
  { id: 501, q: "Decir «te quiero» con hechos además de palabras…", options: ["Es lo que sostiene el compromiso", "Es innecesario", "Es cursi", "Es control"], answer: 0, why: "Las palabras dicen, los hechos confirman." },
  { id: 502, q: "Cuando el compromiso se siente como una carga, lo más sano es…", options: ["Aguantar en silencio", "Culpar al otro", "Huir sin hablar", "Hablarlo y revisar qué está pesando"], answer: 3, why: "Hablar de lo que pesa a tiempo evita que se rompa en silencio." },
  { id: 503, q: "Elegir a tu pareja cada día, incluso en lo cotidiano, es…", options: ["Aburrido", "Lo que mantiene vivo un compromiso real", "Innecesario", "Una carga"], answer: 1, why: "El amor se elige en lo diario, no solo en los grandes momentos." },
  { id: 504, q: "La intimidad también incluye…", options: ["Solo lo físico", "Solo hablar", "Reír, llorar y apoyarse en lo difícil", "Evitar lo incómodo"], answer: 2, why: "La intimidad real abraza lo bueno y lo difícil por igual." },
  { id: 505, q: "Dividir una meta grande en pasos pequeños…", options: ["La hace más difícil", "Es perder tiempo", "La vuelve posible y te muestra avance", "Es innecesario"], answer: 2, why: "Un paso pequeño a la vez convierte lo imposible en un camino." },
  { id: 506, q: "Revisar tus metas cada cierto tiempo…", options: ["Te permite ajustar el rumbo sin perder el norte", "Es perder el tiempo", "Te hace dudar siempre", "Solo sirve al inicio"], answer: 0, why: "Revisar no es dudar: es cuidar que sigas hacia donde quieres." },
  { id: 507, q: "Una meta realista es…", options: ["La más fácil", "Un reto alcanzable con esfuerzo y tiempo", "Imposible", "La que otros te imponen"], answer: 1, why: "Un reto alcanzable te estira sin romperte." },
  { id: 508, q: "Si una meta no se cumple en el tiempo que pensabas…", options: ["Eres un fracaso", "Hay que abandonarla", "No sirves para eso", "Puedes ajustar el plan sin abandonar el sueño"], answer: 3, why: "Ajustar el plan no es rendirse: es seguir con más sabiduría." },
  { id: 509, q: "Celebrar el primer paso hacia una meta…", options: ["Es presumir", "Es innecesario", "Es conformarse", "Te da fuerza para seguir"], answer: 3, why: "Celebrar el primer paso te recuerda que ya estás en camino." },
  { id: 510, q: "Pedir apoyo para lograr una meta es…", options: ["Debilidad", "Inteligente: nadie llega solo a todas partes", "Molestar", "Fracasar"], answer: 1, why: "Pedir apoyo no te hace menos capaz: te hace más acompañado." },
  { id: 511, q: "Una meta que depende solo de ti…", options: ["Te da más control sobre tu avance", "Es egoísta", "No vale", "Es imposible"], answer: 0, why: "Cuando la meta depende de ti, tu esfuerzo sí cuenta." },
  { id: 512, q: "Cambiar de meta en el camino…", options: ["Es fracasar", "Está prohibido", "Es válido si ya no te representa", "Es perder todo"], answer: 2, why: "Cambiar de rumbo no borra lo aprendido: lo lleva contigo." },
  { id: 513, q: "Dedicar tiempo a un proyecto que te apasiona…", options: ["Es perder tiempo", "Te reconecta con tu energía y tus ganas", "Es egoísmo", "No cambia nada"], answer: 1, why: "La pasión por algo propio devuelve las ganas de vivir." },
  { id: 514, q: "Revisar tus metas cada cierto tiempo sirve para…", options: ["Criticar todo", "Compararte", "Rendirse", "Ver tu avance y ajustar el rumbo"], answer: 3, why: "Revisar te muestra cuánto avanzaste y hacia dónde seguir." },
  { id: 515, q: "La paciencia con tus metas es importante porque…", options: ["Todo llega solo", "No hay que esforzarse", "Lo que vale la pena lleva tiempo", "Hay que apurarse"], answer: 2, why: "Lo bueno se construye con tiempo, no con prisa." },
  { id: 516, q: "Un sueño y una meta se diferencian en que…", options: ["La meta tiene pasos y fecha, el sueño solo se imagina", "Son lo mismo", "El sueño es mejor", "La meta es aburrida"], answer: 0, why: "Ponerle pasos y fecha a un sueño lo convierte en un plan." },
  { id: 517, q: "Probar algo nuevo que siempre quisiste hacer…", options: ["Te ayuda a descubrir quién eres hoy", "Es perder tiempo", "Es peligroso", "Es egoísmo"], answer: 0, why: "Probar algo nuevo te presenta a una versión de ti que no conocías." },
  { id: 518, q: "Volver a un hobby que dejaste por tu relación…", options: ["Es retroceder", "Es perder tiempo", "Es recuperar una parte de ti", "Es egoísmo"], answer: 2, why: "Ese hobby era tuyo antes: volver a él es volver a ti." },
  { id: 519, q: "Decidir por ti sin consultar a nadie, de vez en cuando…", options: ["Es egoísmo", "Es grosero", "Está mal", "Es ejercer tu autonomía"], answer: 3, why: "Decidir por ti es recordar que tu vida te pertenece." },
  { id: 520, q: "Retomar amistades que descuidaste durante tu relación…", options: ["Es imposible", "Es sanar una parte de tu vida que extrañabas", "Es traición", "No vale la pena"], answer: 1, why: "Las amistades que te quieren suelen estar esperando tu regreso." },
  { id: 521, q: "Tu identidad después de una ruptura…", options: ["Se perdió", "Depende de tu ex", "Sigue ahí: eres más que una relación", "Hay que inventarla desde cero"], answer: 2, why: "Fuiste alguien antes, durante y después: tu identidad no se fue con nadie." },
  { id: 522, q: "Vestirte o arreglarte como a ti te gusta…", options: ["Es vanidad", "Es presumir", "No importa", "Es expresar quién eres"], answer: 3, why: "Tu estilo es tu forma de decir «este soy yo» sin palabras." },
  { id: 523, q: "Crear rutinas que son solo tuyas…", options: ["Te da estabilidad y un sentido de hogar en ti", "Es aburrido", "Es egoísmo", "No sirve"], answer: 0, why: "Tus rutinas son tu casa: te sostienen cuando todo cambia." },
  { id: 524, q: "Dejar de presentarte como «la pareja de alguien» y ser tú…", options: ["Es triste", "Es recuperar tu nombre y tu historia", "Es egoísmo", "Es imposible"], answer: 1, why: "Tu nombre es tuyo: ser tú no necesita apellido de nadie." },
  { id: 525, q: "Mirar atrás para aprender, no para culparte, significa…", options: ["Olvidar todo", "Preguntarte qué te enseñó sin castigarte", "Repetir la historia", "Culpar al otro de todo"], answer: 1, why: "El pasado enseña mejor cuando lo miras sin látigo." },
  { id: 526, q: "Escribir la lección que te dejó una relación…", options: ["Te ayuda a no repetirla y a soltarla", "Es perder tiempo", "Es revivir el dolor", "No sirve"], answer: 0, why: "Poner la lección en palabras la convierte en sabiduría." },
  { id: 527, q: "Agradecer lo aprendido sin justificar el daño significa…", options: ["Que estuvo bien lo que pasó", "Que debes volver", "Que rescatas la lección sin aprobar la herida", "Que olvidaste"], answer: 2, why: "Puedes agradecer lo aprendido y a la vez saber que no merecías el daño." },
  { id: 528, q: "Preguntarte «¿qué haría distinto hoy?»…", options: ["Es torturarte", "Es inútil", "Es vivir en el pasado", "Es convertir el pasado en guía para el futuro"], answer: 3, why: "Esa pregunta transforma errores en brújula." },
  { id: 529, q: "Reconocer hoy las señales que antes ignorabas…", options: ["Es culparte", "Es tarde", "No sirve", "Es prueba de que creciste"], answer: 3, why: "Ver hoy lo que antes no veías es crecimiento puro." },
  { id: 530, q: "El pasado como maestro, no como cárcel, significa…", options: ["Olvidarlo todo", "Vivir en él", "Aprender y seguir adelante sin quedarte atrapado", "Repetirlo"], answer: 2, why: "El pasado enseña cuando lo visitas, no cuando vives en él." },
  { id: 531, q: "Contar tu historia sin que te duela como antes…", options: ["Es fingir", "Es señal de que la herida está sanando", "Es olvidar", "Es imposible"], answer: 1, why: "Cuando la historia ya no te tumba, la herida está cerrando." },
  { id: 532, q: "Lo que cambió en ti después de una ruptura difícil…", options: ["Puede ser tu mayor fortaleza hoy", "No importa", "Es solo dolor", "Hay que esconderlo"], answer: 0, why: "Lo que te rompió también te enseñó a reconstruirte." },
  { id: 533, q: "Escuchar a alguien que está pasando por una ruptura, sin juzgar…", options: ["Es el mejor apoyo que puedes darle", "Es perder tiempo", "Es meterte", "No ayuda"], answer: 0, why: "Ser escuchado sin juicio es lo que más alivia un corazón roto." },
  { id: 534, q: "Acompañar a un amigo en su duelo sin imponer consejos…", options: ["Es no ayudar", "Es respetar su ritmo y estar presente", "Es indiferencia", "Es debilidad"], answer: 1, why: "Estar presente sin imponer respeta su proceso." },
  { id: 535, q: "Respetar el ritmo de sanación de otra persona significa…", options: ["Apurarla", "Decirle que ya supere", "Compararla contigo", "No exigirle que sane como tú lo hiciste"], answer: 3, why: "Cada quien sana a su ritmo: respetar eso también es amor." },
  { id: 536, q: "Si alguien te pide ayuda y no sabes qué decir…", options: ["Inventar consejos", "Ignorarlo", "Acompañar en silencio y sugerir apoyo profesional si hace falta", "Decirle que exagera"], answer: 2, why: "No necesitas todas las respuestas: acompañar ya es mucho." },
  { id: 537, q: "Hacer planes para dentro de seis meses…", options: ["Es inútil", "Es soñar despierto", "Es decirle a tu corazón que hay futuro", "Es arriesgado"], answer: 2, why: "Planear a futuro es un acto de esperanza." },
  { id: 538, q: "La esperanza después de una ruptura…", options: ["Muere para siempre", "Se practica: se alimenta con pequeños pasos", "Es ingenua", "Es mentira"], answer: 1, why: "La esperanza no llega sola: se construye con cada paso pequeño." },
  { id: 539, q: "Soñar de nuevo con una vida feliz…", options: ["Es tu derecho: el dolor no canceló tu futuro", "Es ingenuo", "Es peligroso", "Es imposible"], answer: 0, why: "Soñar de nuevo no es ingenuo: es valiente." },
  { id: 540, q: "Imaginar tu vida dentro de un año, feliz y en paz…", options: ["Es perder tiempo", "Es imposible", "Es egoísta", "Es una forma de darle dirección a tu sanación"], answer: 3, why: "Imaginar hacia dónde vas le da sentido a cada paso de hoy." },
];
